/* 자동 생성 — 개념카드/굽기.py. 손으로 고치지 말 것 */
window.CARD={"#10":{"묶음":[{"머리":"평가의 기준(차원)","줄":[{"t":"효과성: 조직(프로그램)의 목표 달성 정도","src":"기출 2021-1, 2023-22"},{"t":"효율성: 투입 대비 산출의 비율. 최소한의 비용으로 최대한의 효과. 자금·시간 투입과 서비스 제공 실적의 비율","src":"기출 2021-1, 2021-24"},{"t":"노력성(노력): 서비스를 받은 클라이언트 수, 목표 달성을 위해 투입된 시간·자원의 양, 담당자의 활동 등 투입된 노력 기준","src":"기출 2022-14, 2023-22"},{"t":"비용 절감은 이용자 욕구 충족 목표와 무관하지 않다. 효율성은 책임성의 한 부분","src":"기출 2021-24"},{"t":"서비스의 질: 서비스 질도 평가의 기준이 될 수 있다","src":"기출 2021-16"},{"t":"영향(impact)·공평성(보충): 영향평가는 프로그램이 문제에 미치는 순수 효과","src":"보충"}]},{"머리":"평가의 유형","줄":[{"t":"형성평가: 프로그램 진행 중에 과정을 파악하는 동태적 분석으로 실시할 수 있다","src":"기출 2021-22"},{"t":"총괄평가: 프로그램 종결 후 실시하는 성과평가","src":"기출 2025-24"},{"t":"2025-24 정답표기는 ㄱ,ㄷ,ㄹ(3번)이나 ㄹ(인과 경로 규명)을 형성평가로 본 설명은 교재 기준 검수 필요. ㄴ(비용-효과분석을 효과성 평가로 본 보기)는 정답표기상 제외","src":"기출 2025-24, 보충"},{"t":"비용-편익분석: 프로그램의 비용과 결과를 금전적 가치로 환산해 평가. 효율성 평가","src":"기출 2023-22, 2025-24"},{"t":"비용-효과분석: 비용과 결과(비금전적 단위)를 비교. 결과의 금전적 가치를 환산하지 않는다","src":"기출 2023-22"},{"t":"효과성 평가를 위해 비용편익분석을 쓰는 것이 아니다. 비용편익분석은 효율성 평가","src":"기출 2021-22"},{"t":"프로그램 평가 활용: 프로그램 수정과 정책 개발 등","src":"기출 2021-22"},{"t":"프로그램 평가의 목적: 책임성 이행(재무·회계적, 전문적 책임). 정책개발은 사회복지실천 이념 개발이 아니다","src":"기출 2024-24"}]},{"머리":"책임성","줄":[{"t":"책임성: 업무수행 결과에 대한 책임뿐만 아니라 업무과정에 대한 정당성을 의미","src":"기출 2022-12"},{"t":"책임성 이행에서 효율성을 배제하고 효과성만 극대화하는 것이 아니다. 둘 다 고려","src":"기출 2022-12"},{"t":"책임성 대상: 정부 및 재정자원제공자, 사회복지조직, 사회복지전문직, 클라이언트","src":"기출 2022-12"},{"t":"클라이언트 집단의 욕구 충족과 사회문제 해결의 증거를 보여줘야 한다. 지역사회와 조직 내 상호작용에서도 정당성 확보","src":"기출 2022-12"},{"t":"공급주체 다양화와 시설 민간위탁으로 책임성 요구가 늘었다. 획일적 기준으로 책임성을 규명하기 어렵다","src":"기출 2025-22"},{"t":"책임성 요구 증가로 서비스 질적평가가 제외된 것이 아니라, 질적 평가가 더 중시된다","src":"기출 2025-22, 2021-16"}]},{"머리":"사회복지시설 평가 제도","줄":[{"t":"보건복지부장관과 시ㆍ도지사는 보건복지부령으로 정하는 바에 따라 시설을 정기적으로 평가하고, 그 결과를 공표하거나 시설의 감독ㆍ지원 등에 반영할 수 있으며 시설 거주자를 다른 시설로 보내는 등의 조치를 할 수 있다","src":"사회복지사업법 제43조의2제1항"},{"t":"평가 결과에 따라 시설 거주자를 다른 시설로 보내는 경우에는 제38조제3항의 조치를 하여야 한다","src":"사회복지사업법 제43조의2제2항"},{"t":"평가 주기: 보건복지부장관 및 시ㆍ도지사는 3년마다 시설에 대한 평가를 실시하여야 한다(4년·5년 주기가 아니다)","src":"사회복지사업법 시행규칙 제27조의2제1항"},{"t":"평가기준은 서비스 최저기준을 고려하여 보건복지부장관이 정한다","src":"사회복지사업법 시행규칙 제27조의2제2항"},{"t":"보건복지부장관과 시ㆍ도지사는 평가 결과를 해당 기관의 홈페이지 등에 게시하여야 한다(비공개 원칙이 아니다)","src":"사회복지사업법 시행규칙 제27조의2제3항"},{"t":"평가 방법 기타 평가에 필요한 사항은 보건복지부장관이 정한다","src":"사회복지사업법 시행규칙 제27조의2제4항"},{"t":"평가 결과는 시설 지원에 반영될 수 있고, 우수기관에는 인센티브가 부여된다","src":"사회복지사업법 제43조의2제1항, 기출 2026-19"},{"t":"평가영역: 시설 및 환경, 재정 및 조직 운영, 이용자의 권리 등. 진행: 자체평가, 현장평가 등. 목적: 운영 효율화·서비스 질 향상","src":"기출 2026-19"},{"t":"우리나라 사회복지시설 평가는 「사회복지사업법」에 근거한다. 1997년 법 개정으로 법제화","src":"기출 2021-22, 2025-2, 2025-22"},{"t":"시설 평가제도는 1990년대에 도입되었다","src":"기출 2023-1"}]},{"머리":"서비스 최저기준","줄":[{"t":"보건복지부장관은 시설에서 제공하는 서비스의 최저기준을 마련하여야 한다","src":"사회복지사업법 제43조제1항"},{"t":"시설 운영자는 최저기준 이상으로 서비스 수준을 유지하여야 한다","src":"사회복지사업법 제43조제2항"},{"t":"서비스 기준 대상시설과 서비스 내용 등 필요한 사항은 보건복지부령으로 정한다","src":"사회복지사업법 제43조제3항"},{"t":"서비스 최저기준 포함 사항: 시설 이용자의 인권","src":"사회복지사업법 시행규칙 제27조제1항제1호"},{"t":"서비스 최저기준 포함 사항: 시설의 환경","src":"사회복지사업법 시행규칙 제27조제1항제2호"},{"t":"서비스 최저기준 포함 사항: 시설의 운영","src":"사회복지사업법 시행규칙 제27조제1항제3호"},{"t":"서비스 최저기준 포함 사항: 시설의 안전관리","src":"사회복지사업법 시행규칙 제27조제1항제4호"},{"t":"서비스 최저기준 포함 사항: 시설의 인력관리","src":"사회복지사업법 시행규칙 제27조제1항제5호"},{"t":"서비스 최저기준 포함 사항: 지역사회 연계","src":"사회복지사업법 시행규칙 제27조제1항제6호"},{"t":"서비스 최저기준 포함 사항: 서비스의 과정 및 결과","src":"사회복지사업법 시행규칙 제27조제1항제7호"},{"t":"서비스 최저기준 포함 사항: 그 밖에 서비스 최저기준 유지에 필요한 사항","src":"사회복지사업법 시행규칙 제27조제1항제8호"},{"t":"시설의 규모는 최저기준 포함 사항 목록에 없다","src":"사회복지사업법 시행규칙 제27조, 기출 2022-16"},{"t":"최저기준 대상시설: 법 제2조제1호 각 목의 법률에 따른 사회복지시설과 사회복지관. 시설 규모·서비스 특성·이용자 수 등을 고려해 보건복지부장관이 정하는 시설은 제외","src":"사회복지사업법 시행규칙 제27조제2항"}]},{"머리":"시설운영위원회·사회복지관","줄":[{"t":"시설의 장은 시설 운영에 관한 사항을 심의하기 위해 시설에 운영위원회를 두어야 한다. 보건복지부령으로 정하는 경우 복수 시설이 공동으로 둘 수 있다","src":"사회복지사업법 제36조제1항"},{"t":"운영위원회 심의사항: 시설운영계획의 수립ㆍ평가 / 사회복지 프로그램의 개발ㆍ평가 / 시설 종사자의 근무환경 개선 / 시설 거주자의 생활환경 개선 및 고충 처리 / 종사자와 거주자의 인권보호 및 권익증진 / 시설과 지역사회의 협력 / 그 밖에 시설의 장이 회의에 부치는 사항","src":"사회복지사업법 제36조제1항제1호~제7호"},{"t":"운영위원 구성원(관할 시장ㆍ군수ㆍ구청장이 임명 또는 위촉): 시설의 장 / 시설 거주자 대표 / 보호자 대표 / 종사자 대표 / 시ㆍ군ㆍ구 소속 사회복지업무 담당 공무원 / 후원자 대표 또는 지역주민 / 공익단체 추천인 / 전문 지식과 경험이 풍부한 사람","src":"사회복지사업법 제36조제2항"},{"t":"시설의 장은 운영위원회에 보고하여야 한다: 시설의 회계 및 예산ㆍ결산 / 후원금 조성 및 집행 / 시설운영과 관련된 사건ㆍ사고","src":"사회복지사업법 제36조제3항"},{"t":"사회복지관은 지역복지증진을 위해 실시할 수 있는 사업: 지역사회 특성과 복지욕구를 고려한 서비스 제공 / 사례관리 사업 / 복지자원 관리·주민교육·조직화 사업 / 그 밖에 지역사회가 요청하는 복지증진 사업","src":"사회복지사업법 제34조의5제1항"},{"t":"사회복지관은 모든 지역주민을 대상으로 서비스를 실시하되 우선 제공 대상: 국민기초생활보장법 수급자·차상위계층 / 장애인·노인·한부모가족·다문화가족 / 직업 및 취업 알선이 필요한 사람 / 보호와 교육이 필요한 유아ㆍ아동ㆍ청소년 / 그 밖에 우선 제공이 필요하다고 인정되는 사람","src":"사회복지사업법 제34조의5제2항"},{"t":"사회복지관의 설치ㆍ운영ㆍ사업ㆍ인력 기준 등은 보건복지부령으로 정한다","src":"사회복지사업법 제34조의5제3항"}]},{"머리":"서비스 품질관리: SERVQUAL, 위험관리","줄":[{"t":"SERVQUAL(파라슈라만·자이다믈·베리) 5차원: 유형성 · 신뢰성 · 반응성(대응성·즉응성) · 확신성 · 공감성","src":"기출 2022-24, 2024-16, 2025-15, 2026-5"},{"t":"유형성(tangible): 시설·장비·서비스 제공자 용모 등의 적합성. 기관·장비 등이 질서정연하고 위생적임, 시설과 작업 환경이 깨끗함","src":"기출 2022-24, 2024-16, 2026-5"},{"t":"신뢰성(reliability): 서비스를 약속한 대로 정확하게 실행","src":"기출 2024-16, 2026-5"},{"t":"반응성(responsiveness, 즉응성): 고객 요청에 신속하게 대응하고 즉시 서비스 제공. 이용자의 요구에 선제 응대하는 능력은 신뢰성이 아니다","src":"기출 2022-24, 2023-16, 2026-5"},{"t":"확신성(assurance): 직원의 지식수준과 정중함, 신뢰와 확신을 심어줄 수 있는 능력, 긍정적 의사소통, 제품·서비스를 정확히 설명","src":"기출 2022-24, 2025-15"},{"t":"공감성(empathy): 고객 욕구에 관심을 갖고 이를 반영한 서비스를 제공, 이용자에 대한 관심과 상황 이해","src":"기출 2022-24, 2026-5"},{"t":"서브퀄 요소에는 신뢰성과 확신성이 포함된다","src":"기출 2021-16, 2023-16"},{"t":"위험관리(Risk Management): 이용자에 대한 서비스 관리 측면과 조직관리 측면을 모두 포함. 위험의 사전예방과 사후관리를 모두 포함. 서비스 질 관리를 위해 필요","src":"기출 2021-16, 2023-15, 2023-16"},{"t":"TQM에서 서비스의 질은 고객의 결정에 의한다","src":"기출 2021-16"},{"t":"서비스 이용자와 제공자 관점의 질적 평가가 중시된다","src":"기출 2021-16"}]}],"함정":[{"x":"서비스 질은 사회복지평가의 기준이 될 수 없다.","o":"서비스 질은 사회복지평가의 기준이 될 수 있다.","src":"기출 2021-16"},{"x":"효과성 평가를 위하여 비용편익분석을 실시한다.","o":"효과성 평가는 목표 달성 정도를 본다. 비용편익분석은 효율성 평가에 쓴다.","src":"기출 2021-22"},{"x":"비용 절감은 서비스 이용자의 욕구 충족을 위한 목표와 관련성이 없다.","o":"비용 절감은 서비스 이용자의 욕구 충족을 위한 목표와 관련이 있다(효율성).","src":"기출 2021-24"},{"x":"책임성 이행측면에서 효율성을 배제하고 효과성을 극대화해야 한다.","o":"책임성 이행에서 효율성과 효과성을 함께 고려한다.","src":"기출 2022-12"},{"x":"집단의 노력보다는 개인의 노력이 품질향상에 더 기여한다고 본다.","o":"TQM은 개인보다 집단(팀)의 노력이 품질향상에 기여한다고 본다.","src":"기출 2022-25"},{"x":"총체적 품질관리(TQM)는 기업의 소비자 만족을 극대화하기 위한 기법이므로 사회복지기관에 적용하기에는 적합하지 않다.","o":"TQM은 사회복지기관에도 적용할 수 있다.","src":"기출 2023-16"},{"x":"총체적 품질관리는 지속적인 개선보다는 현상유지에 초점을 둔다.","o":"TQM은 현상유지보다 지속적 개선에 초점을 둔다.","src":"기출 2023-16"},{"x":"서브퀄(SERVQUAL)의 요소에 확신성(assurance)은 포함되지 않는다.","o":"SERVQUAL에는 확신성(assurance)이 포함된다.","src":"기출 2023-16"},{"x":"서브퀄에서 유형성(tangible)은 고객 요청에 대한 즉각적 반응을 말한다.","o":"유형성(tangible)은 시설·장비·직원 용모를 말한다. 즉각적 반응은 반응성.","src":"기출 2023-16"},{"x":"책임성 요구가 증가하면서 사회복지서비스에 대한 질적평가는 제외되었다.","o":"책임성 요구가 늘면서 질적 평가가 더 중시된다.","src":"기출 2025-22"},{"x":"즉응성: 기관, 장비 등이 질서정연하고 위생적임","o":"즉응성(반응성): 신속히 대응해서 즉시 서비스를 제공함. 질서정연·위생적 기관과 장비는 유형성.","src":"기출 2026-5"},{"x":"공감성: 신속히 대응해서 즉시 서비스를 제공함","o":"공감성: 고객 욕구에 관심을 갖고 이를 반영한 서비스를 제공함. 신속 대응은 반응성.","src":"기출 2026-5"},{"x":"확신성: 시설과 작업 환경이 깨끗함","o":"확신성: 직원의 지식·정중함·신뢰와 확신을 주는 능력. 깨끗한 시설·작업 환경은 유형성.","src":"기출 2026-5"},{"x":"유형성: 고객 욕구에 관심을 갖고 이를 반영한 서비스를 제공함","o":"유형성: 시설·장비·직원 용모가 질서정연하고 깨끗함. 고객 욕구에 관심을 두는 것은 공감성.","src":"기출 2026-5"},{"x":"「사회복지사업법」 에 근거하여 4년 주기로 평가가 이루어진다.","o":"평가는 「사회복지사업법」에 근거하며 3년마다 실시한다.","src":"사회복지사업법 시행규칙 제27조의2제1항"}]},"#12":{"묶음":[{"머리":"사회복지 전달체계의 구분","줄":[{"t":"전달체계는 공공 전달체계, 민간 전달체계, 공공과 민간 혼합 전달체계로 구분한다. 우리나라는 혼합 전달체계","src":"기출 2025-17, 2022-22"},{"t":"구조·기능 차원에서 행정체계와 집행체계로 구분. 집행체계는 수급자와 대면 관계를 통해 서비스를 제공","src":"기출 2022-22, 2025-17"},{"t":"공공 행정체계와 민간 행정체계로 구성. 중앙정부의 사회복지 담당 부처는 보건복지부. 지방자치단체의 사회복지 행정체계는 일반 행정체계에 포함","src":"기출 2021-3"},{"t":"사회복지 행정체계에는 영리 사업자도 참여한다. 민간 사회복지기관도 국가나 지방자치단체의 보조금을 받는다","src":"기출 2021-3"},{"t":"행정복지센터, 공단은 공공 전달체계. 사회복지법인은 민간 전달체계(셋 모두 공공이라는 설명은 오답)","src":"기출 2025-17"},{"t":"전달체계: 사회복지서비스 공급자와 소비자를 연결하는 조직적·체계적 장치","src":"기출 2025-17"},{"t":"사회복지서비스 급여의 유형과 전달체계 특성은 관련이 있다","src":"기출 2022-22"},{"t":"서비스 제공기관을 의도적으로 중복해서 만드는 것이 전달체계를 개선해 줄 수도 있다","src":"기출 2022-22"},{"t":"전달체계는 사회복지의 책임성을 이행할 수 있도록 구축되어야 한다","src":"기출 2021-22"}]},{"머리":"전달체계 구축 원칙","줄":[{"t":"통합성: 서비스의 중복과 누락 방지, 다양한 서비스를 통합적으로 제공. 원스톱 방식, 지역사회통합돌봄, 서비스 단편성·비연속성 해결","src":"기출 2021-18, 2025-16, 2026-10"},{"t":"포괄성: 복합적인 욕구들이 빠짐없이 충족되도록 한다. 한 가지 욕구에 전문가 집단이 개입하는 방식이 아니다","src":"기출 2021-18, 2026-10"},{"t":"적절성: 서비스의 양과 질, 제공 기간이 서비스 수요자의 욕구 충족과 목표 달성에 적합해야 한다","src":"기출 2021-18, 2024-18, 2026-10"},{"t":"접근성: 공간·시간·정보·재정 등 제약 없이 서비스를 이용. 서비스 이용자의 비용 부담도 고려한다. 비용 부담을 낮추면 접근성이 높아진다","src":"기출 2021-18, 2024-18, 2026-10"},{"t":"전문성: 충분한 사회복지전문가의 확보가 필요. 최소 비용으로 최대 효과를 얻는 것은 전문성이 아니라 효율성에 해당","src":"기출 2021-18, 2024-18"},{"t":"연속성(지속성): 서비스 간 연계성을 강화하면 높아진다. 필요한 서비스가 파편화되지 않도록 한다(연계성)","src":"기출 2024-18, 2026-10"},{"t":"책임성: 이용자의 요구나 불만을 파악함으로써 높일 수 있다","src":"기출 2024-18"},{"t":"전달체계 접근성을 높이려면 서비스 이용의 장애요인을 줄여야 한다","src":"기출 2022-22"}]},{"머리":"사회복지조직의 환경변화","줄":[{"t":"사회복지 공급주체의 다양화, 성과에 대한 강조와 마케팅 활성화, 기업의 경영관리 기법 도입","src":"기출 2022-15, 2023-25"},{"t":"행정관리능력 향상으로 거주시설이 대규모화되는 것이 환경변화가 아니다(탈시설화·소규모화)","src":"기출 2022-15, 보충"},{"t":"책임성 요구 증가, 소비자주권 강화, 빅데이터 활용 증가, 사회서비스 공급에 민간 참여 증가. 기업 경영관리 기법 도입은 줄지 않고 늘고 있다","src":"기출 2023-25, 2025-23"},{"t":"사회서비스 확대로 사회적 일자리 창출. 지방자치단체 주민참여 활성화. 주민센터를 행정복지센터로 개편","src":"기출 2021-25"},{"t":"성과(outcome) 중심 평가가 강조된다. 산출(output) 중심으로 전환되는 것이 아니다","src":"기출 2025-23"},{"t":"국가가 직접 제공하는 서비스가 늘기보다 민간 참여가 늘고 있다. 사회복지행정의 이론적 준거틀은 여전히 필요. 서비스 다양화로 전문가 활용이 늘고 있다","src":"기출 2025-23"},{"t":"사회서비스 개념은 기존 사회복지서비스를 포괄한다. 사회서비스는 단일 공급주체가 아니라 다양한 주체가 제공","src":"기출 2023-15"},{"t":"읍ㆍ면ㆍ동 중심의 서비스 제공 노력. 지역사회 통합돌봄 시행으로 지역사회 내 보건복지 서비스 제공 확대","src":"기출 2023-15"},{"t":"지역사회 통합돌봄 도입: 전문직종 간 서비스 연계 제공. 생활시설 거주자의 퇴소를 금지하지 않으며 사회서비스가 대폭 축소되는 것이 아니다","src":"기출 2021-25, 2026-20"},{"t":"최근 강조: 디지털 기반·증거 기반 복지행정 역량, 지역사회 생활권 중심의 생애주기별 돌봄정책, 민관협력 통합사례관리, 욕구별 통합서비스 연계·협업","src":"기출 2026-20"}]},{"머리":"네트워크와 거버넌스","줄":[{"t":"지역복지 거버넌스: 지역 내 공공기관·전문기관·학교·시민단체 등이 참여하는 지역 네트워크(예: 지역아동보호네트워크)로 신속한 신고·접수·대응","src":"기출 2021-7"},{"t":"지역사회보장협의체: 지역복지의 민관 협력 거버넌스 기구. 지역사회복지협의체에서 명칭이 바뀌었다","src":"기출 2024-17, 보충"},{"t":"협치(거버넌스): 정부·시장·시민사회가 함께 운영하는 방식","src":"기출 2023-6"},{"t":"지역사회보장협의체의 법령상 구성·기능은 「사회보장급여의 이용ㆍ제공 및 수급권자 발굴에 관한 법률」에 근거(원문 미확인)","src":"보충(원문 미확인)"}]}],"함정":[{"x":"민간 사회복지기관은 국가나 지방자치단체의 보조금을 받지 않는다.","o":"민간 사회복지기관도 국가나 지방자치단체의 보조금을 받는다.","src":"기출 2021-3"},{"x":"포괄성: 클라이언트의 다양한 욕구 중 한 가지 욕구를 해결하기 위하여 전문가 집단이 개입하 는 방식이다.","o":"포괄성: 클라이언트의 복합적인 욕구가 빠짐없이 충족되도록 한다. 한 가지 욕구에 전문가 집단이 개입하는 것이 아니다.","src":"기출 2021-18"},{"x":"지역사회 통합돌봄 추진에 따라 생활시설 거주자의 퇴소를 금지하고 있다.","o":"지역사회 통합돌봄 추진으로 생활시설 거주자의 퇴소를 금지하지 않는다. 지역사회 전환을 지원한다.","src":"기출 2021-25"},{"x":"사회복지서비스 급여의 유형과 전달체계 특성은 관련이 없다.","o":"사회복지서비스 급여의 유형과 전달체계 특성은 관련이 있다.","src":"기출 2022-22"},{"x":"사회서비스는 단일한 공급주체에 의해 제공된다.","o":"사회서비스는 다양한 공급주체가 제공한다.","src":"기출 2023-15"},{"x":"기업의 경영관리 기법 도입이 줄어들고 있다.","o":"기업의 경영관리 기법 도입이 늘어나고 있다.","src":"기출 2023-25"},{"x":"최소 비용으로 최대 효과를 얻음으로써 전문성을 높일 수 있다.","o":"최소 비용으로 최대 효과를 얻는 것은 효율성이다. 전문성은 충분한 전문가 확보.","src":"기출 2024-18"},{"x":"행정복지센터, 공단, 사회복지법인은 공공 전달체계이다.","o":"행정복지센터, 공단은 공공 전달체계이고 사회복지법인은 민간 전달체계다.","src":"기출 2025-17"},{"x":"국가가 직접 제공하는 서비스가 늘어나고 있다.","o":"국가 직접 제공보다 민간 참여가 늘고 있다.","src":"기출 2025-23"},{"x":"성과(outcome) 중심 평가에서 산출(output) 중심 평가로 전환되고 있다.","o":"산출(output) 중심에서 성과(outcome) 중심 평가로 전환되고 있다.","src":"기출 2025-23"},{"x":"사회복지행정의 이론적 준거틀이 필요 없게 되었다.","o":"사회복지행정의 이론적 준거틀은 여전히 필요하다.","src":"기출 2025-23"},{"x":"사회복지서비스가 다양화되면서 전문가 활용이 감소하고 있다.","o":"서비스가 다양화되면서 전문가 활용이 늘고 있다.","src":"기출 2025-23"},{"x":"접근성: 서비스 이용자의 비용 부담은 고려하지 않는다.","o":"접근성: 서비스 이용자의 비용 부담도 고려한다.","src":"기출 2026-10"},{"x":"지역사회 통합돌봄(커뮤니티 케어) 시행에 따라 사회서비스가 대폭 축소되고 있다.","o":"지역사회 통합돌봄은 지역사회 내 서비스 연계를 확대하는 것이지 사회서비스를 대폭 축소하는 것이 아니다.","src":"기출 2026-20"}]},"#3":{"묶음":[{"머리":"고전이론: 과학적 관리론(테일러)","줄":[{"t":"과학적 관리론(테일러): 조직 구성원의 업무를 과학적으로 분석한다(시간·동작 연구, 표준시간·표준동작)","src":"기출 2021-4, 2022-4, 2024-5"},{"t":"과학적 관리론: 경제적 보상(차별성과급·인센티브)으로 생산성을 극대화한다","src":"기출 2021-4, 2024-5, 2026-8"},{"t":"과학적 관리론: 업무의 표준화·분업화로 직무능률을 높인다","src":"기출 2026-8"},{"t":"과학적 관리론: 집권화와 위계구조가 성과의 결정 요인이라고 보지 않는다. 호손 실험 결과를 반영하지 않았다(호손은 인간관계론)","src":"기출 2021-4"},{"t":"과학적 관리론은 관리자에게만 목표 설정 책임을 주고 직원의 의사결정 참여를 지향하지 않아, 참여를 중시하는 사회복지조직에 적용에 한계가 있다","src":"기출 2022-3"},{"t":"과학적 관리론은 조직을 폐쇄체계로 본다","src":"기출 2026-8"},{"t":"테일러 4원칙: 과학적 연구, 과학적 선발·훈련, 노사 협력, 관리자와 작업자의 업무·책임 분담","src":"보충"},{"t":"페이욜(행정관리론): 관리 5기능(계획·조직·명령·조정·통제), 관리 14원칙","src":"보충"}]},{"머리":"고전이론: 관료제이론(베버)","줄":[{"t":"베버 이상적 관료제: 공식적 위계와 업무처리 구조(권한의 위계)","src":"기출 2023-5, 2024-5"},{"t":"관료제: 전문성에 근거한 분업구조, 직무 범위와 권한의 명확화, 규칙에 의해 조직 기능 제한","src":"기출 2023-5"},{"t":"관료제: 비정실성(사적 감정 배제), 문서화, 표준 운영 절차로 합리성·전문성 추구","src":"기출 2024-5, 2025-3"},{"t":"베버가 말한 권위 3유형: 전통적·카리스마적·합법적. 관료제의 권위는 합법적 권위다. '전통적 권위에 의한 조직 통제'는 이상적 관료제가 아니다","src":"기출 2023-5, 보충"},{"t":"관료제는 수평적 권한 구조를 가정하지 않는다. 수직적 위계 구조를 가정한다","src":"기출 2026-14"},{"t":"관료제의 역기능: 목적전치(수단이 목적을 대체), 번문욕례, 변화에 둔감","src":"보충"}]},{"머리":"인간관계이론","줄":[{"t":"인간관계론(메이요 호손 실험): 인간의 사회적·심리적·정서적 욕구 강조","src":"기출 2023-4"},{"t":"인간관계론: 조직 내 비공식 집단의 중요성 인식, 개인은 감정적이며 비물질적 보상에 민감하다","src":"기출 2023-4"},{"t":"인간관계론: 인간을 심리적·사회적 욕구를 가진 전인격적 존재로 파악","src":"기출 2025-3"},{"t":"호손 연구: 생산성은 근로조건·환경에만 좌우되지 않는다. 심리적 요인과 사회적 상호작용이 생산성에 긍정적 영향을 준다","src":"기출 2024-3"},{"t":"호손 연구: 근로자는 집단 구성원으로서 행동하고 반응한다. 공식 부서 형성이 아니라 비공식 집단이 영향을 준다","src":"기출 2024-3"},{"t":"인간관계이론의 관련 이론: 호손연구, 욕구계층 이론, XY 이론. 목표는 생산성 향상이며 직원 만족·보상만이 최고 목표가 아니다","src":"기출 2026-8"},{"t":"호손 실험 단계(보충): 조명 실험 -> 계전기 조립 -> 면접 -> 뱅크 배선 관찰","src":"보충"}]},{"머리":"동기이론","줄":[{"t":"매슬로우 욕구단계: 생리 - 안전 - 사회적(애정·소속) - 존경 - 자아실현의 5단계. 존재·관계·성장 3단계는 앨더퍼 ERG","src":"기출 2022-17, 보충"},{"t":"앨더퍼 ERG: 존재(Existence)·관계(Relatedness)·성장(Growth) 욕구. 고순위 욕구가 좌절되면 저순위 욕구를 더 원하는 좌절-퇴행 개념","src":"기출 2022-17"},{"t":"허즈버그 동기-위생이론: 불만을 일으키는 요인은 위생요인이다. 동기요인(성취·인정·일 자체·책임·승진·성장)이 만족을 높인다","src":"기출 2022-17, 2025-8"},{"t":"위생요인: 급여, 근로조건, 기술적 감독, 대인관계, 정책·관리, 지위, 안정. 성취에 대한 인정은 동기요인","src":"기출 2025-8"},{"t":"직원 불만족 요인을 낮추기 위해 급여 인상, 사무실 리모델링을 한 것은 허즈버그 이론 적용(위생요인 개선)","src":"기출 2024-10"},{"t":"맥그리거 XY이론: X이론은 감독·보상과 처벌·지시가 필요하다고 본다. Y이론은 동기부여와 자율적 운영이 중요하다고 본다","src":"기출 2024-4, 2026-14"},{"t":"조직에 대한 기대와 현실 간 차이가 동기수준을 결정한다고 보는 이론은 맥그리거 XY가 아니라 브룸의 기대이론 계열","src":"기출 2022-17, 보충"},{"t":"맥클리랜드 성취동기이론: 성취·권력·친교 욕구. 조직 공정성이 핵심은 아니다(공정성은 아담스)","src":"기출 2022-17, 보충"},{"t":"브룸 기대이론: 노력-성과(기대), 성과-결과(수단성), 결과-가치(유의성)의 연계를 강조한다. 제도와 절차 강조는 아니다","src":"기출 2026-1"},{"t":"아담스 공정성(형평성)이론: 투입 대비 산출의 비율을 타인과 비교해 형평성을 느낀다. 보상 형평성 확보와 직원의 인식 점검이 핵심","src":"기출 2026-25, 보충"},{"t":"로크 목표설정이론, 아지리스 미성숙-성숙이론도 동기이론 계열","src":"보충"}]},{"머리":"체계이론·상황이론·기타 조직이론","줄":[{"t":"체계이론: 조직은 유기적으로 상호작용하는 다양한 하위체계로 구성된다. 투입-전환-산출-환류","src":"기출 2026-14"},{"t":"체계이론 용어(보충): 개방체계·폐쇄체계, 엔트로피, 항상성, 동귀결성(등종국성)","src":"보충"},{"t":"상황이론: 효과적인 관리 방법은 조직이 처한 환경과 조건에 따라 달라진다. 모든 경우에 적용되는 최선의 이론은 없다","src":"기출 2021-5, 2025-3"},{"t":"상황이론: 조직을 개방체계로 본다. 외부 환경(사회·정치·경제·문화 변수)을 고려한다. 폐쇄체계로 보며 내부 상황에만 초점이라는 설명은 틀리다","src":"기출 2022-4, 2024-4, 2026-14"},{"t":"상황이론 학자(보충): 로렌스와 로쉬(분화·통합), 번스와 스토커(기계적/유기적), 우드워드(기술), 톰슨","src":"보충"},{"t":"정치경제이론: 경제적 자원과 권력 간 상호작용 강조","src":"기출 2024-4"},{"t":"학습조직이론: 개인 및 조직의 학습공유를 통한 역량강화","src":"기출 2024-4"},{"t":"학습조직 5가지 구축요인(센게): 자기숙련(개인 학습 의지), 사고모형, 공유비전, 팀학습, 시스템 사고","src":"기출 2022-7, 보충"},{"t":"시스템 사고: 전체와 부분 간 역동적 관계를 이해. 공유비전은 개인 비전 유지가 아니라 함께 지향하는 비전","src":"기출 2022-7"},{"t":"팀학습은 최고관리자 감독·통제를 통한 학습이 아니다. 사고모형은 계층적 수직구조 이해가 아니다","src":"기출 2022-7"},{"t":"자원의존이론(페퍼와 샐런식): 조직은 외부 자원에 의존하며 환경과 교환 관계를 맺는다","src":"보충"},{"t":"제도이론(디마지오와 파월): 동형화 - 강압적·모방적·규범적","src":"보충"}]},{"머리":"총체적 품질관리(TQM)와 현대 조직운영 기법","줄":[{"t":"TQM: 지속적인 품질개선(현상유지가 아니다)을 강조하는 일련의 과정","src":"기출 2022-25, 2023-16"},{"t":"TQM: 자료와 사실에 기반한 의사결정, 조직구성원 훈련 강조","src":"기출 2022-25"},{"t":"TQM: 좋은 품질은 고객이 결정한다. 서비스의 질은 서비스 제공 이후가 아니라 과정 전체에서 고려한다","src":"기출 2022-25, 2026-11"},{"t":"TQM: 품질이 조직의 일차적인 목적이고, 조직 내 변화는 지속적으로 이루어져야 한다. 품질은 직원 모두가 결정한다는 설명은 오답(고객이 결정)","src":"기출 2026-11"},{"t":"TQM: 집단(팀)의 노력을 중시한다. 개인의 노력이 더 기여한다고 보지 않는다","src":"기출 2022-25"},{"t":"TQM은 기업 소비자 만족을 위한 기법이지만 사회복지기관에도 적용 가능하다","src":"기출 2023-16"},{"t":"TQM 학자(보충): 데밍(PDCA, 14원칙), 주란, 크로스비(무결점). 사회복지 적용: 스위스(Swiss), 마틴(Martin)","src":"보충"},{"t":"리스트럭처링(restructuring): 중복사업 통합 등으로 조직 경쟁력 확보","src":"기출 2022-6"},{"t":"리엔지니어링(re-engineering): 업무 과정을 근본적으로 재설계해 서비스 시간 단축","src":"기출 2022-6"},{"t":"벤치마킹(benchmarking): 우수한 대상을 찾아 뛰어난 부분을 배움","src":"기출 2022-6"},{"t":"아웃소싱(outsourcing): 계약을 통해 외부 전문가에게 조직 기능 일부를 의뢰","src":"기출 2022-6"},{"t":"균형성과표(BSC): 직원 면접평가표가 아니다. 성과를 재무·고객·내부프로세스·학습과 성장 4관점으로 관리","src":"기출 2022-6, 보충"},{"t":"목적전치(goal displacement): 성과 지표(모금실적 평가)에 몰두해 본래 목표(프로그램 성과)가 뒷전이 되는 현상","src":"기출 2023-9"},{"t":"크리밍(creaming): 성과를 높이려고 서비스가 쉬운 클라이언트만 선택하는 현상","src":"기출 2023-9, 보충"},{"t":"소진(burn out), 다운사이징(downsizing, 인원·조직 축소)","src":"보충"}]},{"머리":"신공공관리론·거버넌스 이론","줄":[{"t":"신공공관리론(NPM): 공공서비스 공급에서 정부실패를 해결하기 위해 대두한 이론","src":"기출 2023-6"},{"t":"NPM: 신자유주의에 이론적 기반. 시장의 경쟁원리를 공공행정에 도입. 공공부문 조직운영에 시장원리 적용","src":"기출 2023-6, 2025-4"},{"t":"NPM: 행정 효율성과 고객 대응성 중시, 규제완화와 조직원 참여, 시민·고객 중심으로 서비스 질 제고","src":"기출 2025-4"},{"t":"NPM은 조직규모 확장과 중앙집권화를 지향하지 않는다(축소·분권). 민간 서비스를 정부가 직접 공급하게 하는 것도 아니다","src":"기출 2025-4, 2023-6"},{"t":"협치(거버넌스): 정부·시장·시민사회의 협력적 운영을 추구","src":"기출 2023-6"},{"t":"목표관리(MBO, 드러커): 목표를 구성원과 함께 설정, 단기·장기 목표 모두. 목표가 장기적으로만 수립되어야 한다는 설명은 오답","src":"기출 2026-14, 보충"}]}],"함정":[{"x":"맥그리거(D. McGregor)의 XㆍY이론은 조직에 대한 기대와 현실 간 차이가 동기수준을 결정한다는 점을 강조한다.","o":"맥그리거 XY이론은 X이론(감독·통제)과 Y이론(자율·동기) 두 인간관을 구분한다. 기대와 현실의 차이로 동기를 설명하는 것은 기대이론.","src":"기출 2022-17"},{"x":"허즈버그(F. Herzberg)의 동기-위생요인 이론은 불만 초래 요인을 동기요인으로 규정한다.","o":"허즈버그: 불만 초래 요인은 위생요인이고, 동기요인은 만족을 높이는 요인이다.","src":"기출 2022-17"},{"x":"맥클리랜드(D. McClelland)의 성취동기이론은 조직 공정성을 성취동기 고취를 위한 핵심요소로 간주한다.","o":"맥클리랜드 성취동기이론은 성취·권력·친교 욕구를 말한다. 조직 공정성이 핵심인 이론은 아담스 공정성이론.","src":"기출 2022-17"},{"x":"매슬로우(A. Maslow)의 욕구단계 이론은 욕구가 존재, 관계, 성장욕구의 세 단계로 구성된다고 주장한다.","o":"매슬로우 욕구단계는 생리·안전·사회·존경·자아실현 5단계. 존재·관계·성장 3단계는 앨더퍼 ERG.","src":"기출 2022-17"},{"x":"민간이 공급하던 서비스를 정부가 직접 공급하도록 하였다.","o":"신공공관리론은 민간이 공급하던 서비스를 정부가 직접 공급하게 한 것이 아니라 민간·시장 원리를 도입했다.","src":"기출 2023-6"},{"x":"생산성은 근로조건과 환경에 의해서만 좌우된다.","o":"생산성은 근로조건·환경뿐 아니라 심리적·사회적 요인에도 좌우된다.","src":"기출 2024-3"},{"x":"사회적 상호작용은 생산성 향상에 부정적인 영향을 미친다.","o":"사회적 상호작용은 생산성 향상에 긍정적 영향을 미친다.","src":"기출 2024-3"},{"x":"공식적인 부서의 형성은 생산성 향상으로 이어진다.","o":"비공식 집단의 형성이 생산성에 영향을 준다(공식 부서 형성이 아님).","src":"기출 2024-3"},{"x":"근로자는 집단 구성원이 아닌 개인으로서 행동하고 반응한다.","o":"근로자는 개인이 아니라 집단 구성원으로서 행동하고 반응한다.","src":"기출 2024-3"},{"x":"조직규모 확장과 중앙집권화를 지향한다.","o":"신공공관리론은 조직규모 축소와 분권화를 지향한다.","src":"기출 2025-4"},{"x":"인간관계이론은 조직의 생산성 향상이 아닌 직원 만족과 보상을 가장 중요한 목표로 한다.","o":"인간관계이론도 생산성 향상을 중요한 목표로 한다(직원 만족과 보상만이 최고 목표가 아니다).","src":"기출 2026-8"},{"x":"관료제이론: 수평적 권한 구조의 특성을 가정한다.","o":"관료제이론: 수직적 위계(권한 구조)를 가정한다.","src":"기출 2026-14"},{"x":"목표관리이론(MBO): 목표는 장기적인 관점에서만 수립되어야 한다고 본다.","o":"MBO: 목표는 단기·장기 관점에서 모두 수립한다.","src":"기출 2026-14"},{"x":"상황이론: 조직은 외부 환경의 영향을 받지 않고 내부적 요인을 통해 발전할 수 있다고 본다.","o":"상황이론: 조직은 개방체계로서 외부 환경의 영향을 받는다고 본다.","src":"기출 2026-14"},{"x":"X이론: 조직관리에서 적절한 동기부여와 자율적 운영이 중요하다고 본다.","o":"X이론: 감독·통제·지시가 필요하다고 본다. 동기부여·자율 운영 중시는 Y이론.","src":"기출 2026-14"}]},"#1":{"묶음":[{"머리":"사회복지행정의 정의와 성격","줄":[{"t":"사회복지행정: 사회복지정책을 사회복지서비스로 전환하는 과정","src":"기출 2025-1, 2026-4"},{"t":"사회복지행정: 조직의 목표(사회복지정책·프로그램)를 달성하기 위해 인적·물적 자원을 동원하고 관리하는 활동","src":"보충"},{"t":"사회복지행정의 대상은 정부조직만이 아니다. 민간 사회복지기관도 포함한다","src":"기출 2025-1"},{"t":"재원은 정부 재정 외에 민간자원(후원금·이용료 등)도 활용한다","src":"기출 2025-1"},{"t":"사회복지행정은 가치판단을 배제하지 않는다. 사회복지 가치와 윤리를 바탕으로 한다","src":"기출 2025-1, 2023-3"},{"t":"사회복지행정가는 가치중립적이어야 하는 것이 아니다. 가치 선택과 윤리적 딜레마에 직면한다","src":"기출 2023-3, 2024-1"},{"t":"재정관리는 사회복지행정에 포함된다. 서비스 효율성도 고려한다","src":"기출 2023-3"},{"t":"직무환경(상황)에 따라 운영이 달라진다. 획일적으로 운영하지 않는다","src":"기출 2023-3"},{"t":"효과성과 효율성은 둘 다 중요하다. 효율성만 앞세우지 않는다","src":"기출 2025-1"},{"t":"추구 가치: 공익성·공평성·접근성 등","src":"기출 2026-4"},{"t":"역할: 지역사회 내 다양한 이해관계 조정, 지역 네트워크·통합사례관리 등을 위한 조직 관리 포함","src":"기출 2026-4"},{"t":"정책·클라이언트·종사자 사이에 조직 목표의 합의점을 찾기가 쉽지 않다","src":"기출 2026-4"}]},{"머리":"사회복지행정의 과정과 기능","줄":[{"t":"행정 실행 과정 순서: 과업 기획 - 과업 조직화 - 과업 촉진 - 과업 평가 - 환류","src":"기출 2022-2"},{"t":"기획(planning): 조직의 목적과 목표 달성 방법을 설정하는 활동","src":"기출 2023-2"},{"t":"조직화(organizing): 업무 분담과 권한·책임 구조를 정하는 활동. 이사회·행정기관에 보고하는 활동이 아니다(그것은 보고 reporting)","src":"기출 2023-2"},{"t":"평가(evaluating): 설정된 목표에 따라 성과를 평가하는 활동","src":"기출 2023-2"},{"t":"인사(staffing): 직원 채용, 해고, 교육, 훈련 등","src":"기출 2023-2"},{"t":"귤릭(Gulick)의 POSDCoRB: 기획·조직·인사·지휘·조정·보고·재정(예산)","src":"보충"},{"t":"사회복지행정가의 능력: 대안 모색, 조직이론 이해, 우선순위 결정, 권한위임과 권한실행. 배타적 사고는 능력이 아니다","src":"기출 2022-1"}]},{"머리":"사회복지조직·휴먼서비스 조직의 특성","줄":[{"t":"하센펠트(Hasenfeld) 휴먼서비스 조직: 인간을 원료(raw material)로 한다","src":"기출 2023-7"},{"t":"하센펠트: 클라이언트와 직접적 관계 속에서 활동하며, 목표가 불확실하고 모호해지기 쉽다","src":"기출 2023-7, 2024-1"},{"t":"하센펠트: 업무과정에서 주로 전문가에 의존한다. 목표 달성 기술이 불확실하다(명확한 지식·기술을 쓴다는 설명은 오답)","src":"기출 2023-7"},{"t":"휴먼서비스 조직: 서비스 효과성을 객관적으로 입증하기 어렵고, 성과 평가가 어렵다","src":"기출 2024-1, 2023-3"},{"t":"클라이언트와 사회복지사의 관계에 따라 서비스 효과성이 좌우된다","src":"기출 2024-1"},{"t":"사회복지사의 전문성과 자율성을 인정한다","src":"기출 2024-1"},{"t":"사회복지조직의 목표는 명확하거나 구체적이기 어렵다","src":"기출 2024-1"},{"t":"하센펠트의 분류: 사람처리조직(분류·지위 부여), 사람유지조직(상태 유지), 사람변화조직(직접 변화)","src":"보충"}]},{"머리":"비영리 사회복지조직","줄":[{"t":"비영리조직: 사적 이익보다 공동체의 이익을 우선 추구한다","src":"기출 2021-6"},{"t":"비영리조직은 필요하면 수익사업을 실시할 수 있다","src":"기출 2021-6, 2026-22"},{"t":"회원 조직도 비영리조직에 포함된다. 회원은 자발적으로 가입한다","src":"기출 2021-6, 2025-5"},{"t":"비영리조직: 기부금·후원금이 중요한 재원이다","src":"기출 2021-6"},{"t":"비영리조직은 세제혜택(조세감면)을 받을 수 있다","src":"기출 2021-6, 2026-22"},{"t":"비영리조직은 이윤이 생겨도 구성원에게 배당하지 않는다(수입 배당 금지)","src":"기출 2025-5, 2026-22"},{"t":"비영리조직은 시장실패와 정부실패를 보완할 수 있다. 지방자치단체 보조금을 받을 수 있다","src":"기출 2025-5"},{"t":"비영리조직은 최소한의 조직 구조와 운영 공식성을 갖는다","src":"기출 2025-5"},{"t":"정부조직보다 관료화 정도가 낮다. 국가·시장이 공급하기 어려운 서비스를 제공한다","src":"기출 2023-24"},{"t":"특정 이익집단을 위한 서비스 제공, 개입대상 선정과 개입방법의 특화가 가능하다","src":"기출 2023-24"},{"t":"수익성과 서비스 질을 고려하지 않고 운영하는 조직이 아니다","src":"기출 2023-24"},{"t":"후원금으로만 운영되는 것이 아니다. 국고보조금·이용료·전입금 등 재원이 다양하다","src":"기출 2026-22"}]}],"함정":[{"x":"한국에는 비영리조직에 대한 세제혜택이 없다.","o":"한국에는 비영리조직에 대한 세제혜택(조세감면)이 있다.","src":"기출 2021-6"},{"x":"사회복지행정가는 가치중립적이어야 한다.","o":"사회복지행정가는 가치중립적이지 않다. 사회복지 가치에 기반한다.","src":"기출 2023-3"},{"x":"서비스 효율성은 고려하지 않는다.","o":"서비스 효율성을 고려한다.","src":"기출 2023-3"},{"x":"재정관리는 사회복지행정에 포함되지 않는다.","o":"재정관리는 사회복지행정에 포함된다.","src":"기출 2023-3"},{"x":"직무환경에 관계없이 획일적으로 운영된다.","o":"직무환경에 따라 운영이 달라진다.","src":"기출 2023-3"},{"x":"수익성과 서비스 질을 고려하지 않고 조직을 운영한다.","o":"사회복지조직은 수익성과 서비스 질을 모두 고려하여 운영한다.","src":"기출 2023-24"},{"x":"서비스의 효과성을 객관적으로 입증하기가 용이하다.","o":"서비스의 효과성을 객관적으로 입증하기가 어렵다.","src":"기출 2024-1"},{"x":"정부조직만을 대상으로 한다.","o":"사회복지행정은 정부조직만이 아니라 민간조직도 대상으로 한다.","src":"기출 2025-1"},{"x":"조직의 효과성보다 효율성이 중요하다.","o":"효과성과 효율성이 모두 중요하다.","src":"기출 2025-1"},{"x":"정부 재정 외에 민간자원 활용은 배제한다.","o":"정부 재정 외에 민간자원도 활용한다.","src":"기출 2025-1"},{"x":"사회문제 해결과정에서 가치판단을 배제한다.","o":"사회복지행정은 가치판단을 배제하지 않는다.","src":"기출 2025-1"},{"x":"이윤이 발생하면 구성원에게 균등하게 배당한다.","o":"비영리조직은 이윤이 발생해도 구성원에게 배당하지 않는다.","src":"기출 2025-5"},{"x":"정책과 클라이언트, 종사자 간 조직 목표에 대한 합의점을 찾기가 용이하다.","o":"정책·클라이언트·종사자 간 조직 목표의 합의점을 찾기가 쉽지 않다.","src":"기출 2026-4"}]},"#4":{"묶음":[{"머리":"조직구조의 3대 변수","줄":[{"t":"복잡성: 조직 활동의 분화 정도. 수평적·수직적·공간적 분화가 높을수록 복잡성이 높아진다","src":"기출 2026-18"},{"t":"수평적 분화: 동일한 위계 수준에서 과업이 나뉘는 형태. 수직적 분화: 조직 계층 수와 관련","src":"기출 2026-18"},{"t":"공간적 분화: 조직 부서가 지역으로 분산될수록 복잡성이 높아진다(낮아지지 않는다)","src":"기출 2026-18"},{"t":"과업분화가 많을수록 수평적 분화가 더 이루어진다. 과업 종류가 많으면 수직적 분화가 늘어난다는 단정은 오답","src":"기출 2024-6, 2023-8"},{"t":"수직적 분화가 많아질수록 의사소통 절차가 복잡해진다","src":"기출 2024-6"},{"t":"공식화: 규칙·절차·문서화의 정도. 공식화 정도가 높을수록 직원의 재량권이 줄어든다","src":"기출 2023-8"},{"t":"조직규모가 커질수록 공식화 정도는 높아지는 경향이다(낮아지지 않는다)","src":"기출 2023-8, 보충"},{"t":"업무가 단순·반복적일수록 공식화 효과가 크다. 업무가 복잡할수록 공식화 효과가 크다는 것은 오답","src":"기출 2024-6, 보충"},{"t":"공식화 수준을 높이면 직무의 사적(개인적) 영향력은 낮아진다","src":"기출 2024-6"},{"t":"집권화: 의사결정 권한이 조직 상층부에 집중. 집권화를 높이면 권한이 집중된다(분산 아님)","src":"기출 2024-6"},{"t":"분권화 정도가 높을수록 하위 계층에 권한이 이양된다. 최고관리자에게 통제권한이 집중되는 것은 집권화","src":"기출 2023-8"},{"t":"집권화가 높을수록 직원의 권한·책임 범위가 모호해지는 것이 아니라 줄어든다","src":"기출 2023-8, 보충"}]},{"머리":"조직구조의 유형","줄":[{"t":"태스크포스(TF): 특정 사업·과제를 위해 기존 부서에서 인력을 파견해 구성. 임시적, 과업 종료 시 해체. 전문가를 배치하며 환경변화 대응 성격이 강하다","src":"기출 2022-5, 2025-7"},{"t":"위원회 구조: 일상 업무수행기구와 별도로 구성, 특별과업·문제해결을 위한 전문가 중심. 수직적 분화와 공식화가 낮다","src":"기출 2024-7"},{"t":"매트릭스 조직: 기능 조직과 프로젝트 조직을 결합. 두 조직의 장점을 살리도록 설계","src":"기출 2026-17"},{"t":"네트워크 조직: 핵심 기능만 갖고 나머지를 외부와의 연계로 수행(보충)","src":"보충"},{"t":"TF는 정해진 기일 동안 기존 조직이 수행하기 어려운 일을 해결하기 위해 임시 편성","src":"기출 2026-17"},{"t":"라인-스탭 조직: 라인(직접 업무)과 스탭(자문·지원) 분리(보충)","src":"보충"},{"t":"민츠버그 5유형: 단순구조, 기계적 관료제, 전문적 관료제, 사업부제(분할형), 애드호크라시","src":"보충"},{"t":"팀제·위원회 도입 효과: 최고관리자의 업무·책임 감소, 직원 자발적 협조 유도, 부서 간 협조 증가, 하위부서 재량권 강화. 위기와 갈등을 신속하게 해결하는 것은 아니다(의사결정 지연)","src":"기출 2025-6"}]},{"머리":"조직환경","줄":[{"t":"조직환경 요인: 경제적 상황, 사회인구적 특성, 과학기술, 법적 규제, 다른 기관과의 경쟁, 정치적 요인","src":"기출 2021-8, 보충"},{"t":"과학기술의 발전은 서비스에 영향을 미친다. 경제적 상황은 서비스 수요에 영향을 미친다. 사회인구적 특성은 사회문제와 밀접하다","src":"기출 2021-8"},{"t":"법적 규제가 많을수록 서비스에 대한 클라이언트의 접근이 제한될 수 있다","src":"기출 2021-8"},{"t":"다른 기관과의 경쟁은 고려 대상이다. 고려하지 않는다는 설명은 오답","src":"기출 2021-8"},{"t":"경직된 조직문화는 불확실한 환경에 대처하도록 돕지 못한다","src":"기출 2024-8"},{"t":"조직환경이론: 상황이론, 자원의존이론, 제도이론, 조직군 생태학이론, 정치경제이론","src":"보충"}]}],"함정":[{"x":"경제적 상황은 서비스 수요에 영향을 미친다.","o":"경제적 상황은 서비스 수요에 영향을 미친다(이 문장이 맞다. 원문은 발문이 '옳지 않은 것'이라 같은 문항의 '다른 기관과의 경쟁은 고려하지 않는다'가 오답. 표식 불일치, 검수 필요).","src":"기출 2021-8"},{"x":"조직규모가 커질수록 공식화 정도가 낮아진다.","o":"조직규모가 커질수록 공식화 정도는 높아지는 경향이다.","src":"기출 2023-8"},{"x":"과업의 종류가 많을수록 수직적 분화가 늘어난다.","o":"과업의 종류가 많을수록 수평적 분화가 늘어난다.","src":"기출 2023-8"},{"x":"분권화 정도가 높을수록 최고관리자에게 조직 통제권한이 집중된다.","o":"분권화 정도가 높을수록 권한이 하위로 분산된다.","src":"기출 2023-8"},{"x":"집권화 정도가 높을수록 직원의 권한과 책임의 범위가 모호해진다.","o":"집권화 정도가 높을수록 상층부에 권한이 집중되고 하위 직원의 권한은 줄어든다.","src":"기출 2023-8"},{"x":"집권화 수준을 높이면 의사결정의 권한이 분산된다.","o":"집권화 수준을 높이면 의사결정 권한이 집중된다.","src":"기출 2024-6"},{"x":"업무가 복잡할수록 공식화의 효과는 더 크다.","o":"업무가 단순·반복적일수록 공식화의 효과가 더 크다.","src":"기출 2024-6"},{"x":"공식화 수준을 높이면 직무의 사적 영향력이 높아진다.","o":"공식화 수준을 높이면 직무의 사적 영향력은 낮아진다.","src":"기출 2024-6"},{"x":"과업분화가 적을수록 수평적 분화가 더 이루어진다.","o":"과업분화가 많을수록 수평적 분화가 더 이루어진다.","src":"기출 2024-6"},{"x":"위기와 갈등을 신속하게 해결할 수 있다.","o":"팀·위원회 방식은 위기와 갈등의 신속한 해결에 불리할 수 있다(의사결정 지연).","src":"기출 2025-6"},{"x":"조직부서가 지역으로 분산될수록 복잡성은 낮아진다.","o":"조직부서가 지역으로 분산될수록 복잡성은 높아진다(공간적 분화).","src":"기출 2026-18"}]},"#5":{"묶음":[{"머리":"리더십 이론 총정리","줄":[{"t":"특성(자질)이론: 리더의 타고난 개인 특성(지능·사회적 지위·교육·외모 등)을 강조","src":"기출 2024-9, 보충"},{"t":"행동이론: 리더의 행동 유형에 초점. 아이오와 연구(권위형·민주형·자유방임형), 오하이오(구조주도·배려), 미시건(직무중심·종업원중심), 관리격자","src":"보충"},{"t":"상황이론: 상황에 따라 적합하게 대응하는 리더십이 효과적","src":"기출 2023-10"},{"t":"관리격자 모형(블레이크와 머튼)은 행동이론이다. 자질이론이 아니다","src":"기출 2022-20"},{"t":"관리격자 축: 생산(일)에 대한 관심 x 인간(사람)에 대한 관심. 효과성·효율성이 아니다","src":"기출 2025-9"},{"t":"관리격자 5유형: 무력형(1.1) · 과업형(9.1) · 컨트리클럽형(1.9) · 중도형(5.5) · 팀형(9.9)","src":"기출 2021-9, 2025-9"},{"t":"무력형(무기력형, 1.1): 일과 사람 모두에 관심이 낮다","src":"기출 2025-9"},{"t":"과업형(9.1): 일에만 관심이 있고 사람에는 거의 관심이 없다","src":"기출 2023-10"},{"t":"컨트리클럽형(1.9): 사람에 대한 관심은 높고 일에 대한 관심은 낮다. 직원 개인 문제에 적극 지원하고 화기애애한 분위기 조성, 사업관리는 팀장에게 일임","src":"기출 2021-9, 2023-10"},{"t":"중도형(5.5): 인간적 요소와 조직성과 간 타협과 균형을 추구","src":"기출 2025-9"},{"t":"팀형(9.9): 일과 사람 모두 높은 관심. 가장 이상적 유형이다. 컨트리클럽형(1.9)·중도형이 이상형이 아니다","src":"기출 2022-20, 2025-9"},{"t":"허시와 블랜차드 상황적 리더십: 구성원의 성숙도를 중요하게 고려. 유형: 지시형 - 설득형 - 참여형 - 위임형","src":"기출 2022-20, 보충"},{"t":"하우스 경로-목적이론: 리더가 부하의 목표 달성 경로를 명확히 해준다. 지시적·지원적·참여적·성취지향적 리더십","src":"기출 2026-2, 보충"},{"t":"피들러 상황적합이론: LPC 점수로 리더 유형 측정, 상황 호의성에 따라 효과가 다름","src":"보충"},{"t":"퀸(Quinn) 경쟁가치 리더십 모형은 행동이론의 대표 모형이 아니다. 조직환경 변화에 따라 리더십이 달라질 수 있다고 본다(상황·조직문화 계열)","src":"기출 2022-20, 보충"},{"t":"퀸 경쟁가치모형 4사분면: 인간관계 모형, 개방체계 모형, 내부과정 모형, 합리적 목표 모형","src":"보충"}]},{"머리":"참여적 리더십·변혁적 리더십·서번트 리더십","줄":[{"t":"참여적 리더십: 조직 목표에 대한 구성원 참여동기 증대, 리더-구성원 의사소통 활발, 집단의 지식·경험·기술 활용 용이","src":"기출 2021-10"},{"t":"참여적 리더십: 하급자가 의사결정에 참여. 동기부여 수준이 높은 업무자로 구성된 조직에 효과적. 책임성 소재가 모호해질 수 있다. 사회복지 가치와 부합","src":"기출 2022-21"},{"t":"참여적 리더십: 의사결정에 시간과 에너지가 더 든다(절약되지 않는다)","src":"기출 2022-21"},{"t":"변혁적 리더십: 구성원이 스스로 혁신하도록 비전을 제시한다(비전·영감)","src":"기출 2022-18"},{"t":"변혁적 리더십: 구성원에 대한 상벌체계 강조는 거래적 리더십. 봉사를 핵심 가치로 하는 것은 서번트 리더십","src":"기출 2022-18"},{"t":"변혁적 리더십은 부하 직원의 변화와 조직의 이익(공동 목표)을 강조한다. 개인의 사적 이익 강조가 아니다","src":"기출 2023-23"},{"t":"변혁적 리더십 4요소(바스): 이상적 영향력(카리스마), 영감적 동기부여, 지적 자극, 개별화된 배려","src":"보충"},{"t":"거래적 리더십(번스): 보상과 처벌을 매개로 한 교환 관계. '가치의 협상과 계약'","src":"기출 2024-9, 보충"},{"t":"서번트(섬김) 리더십(그린리프): 인간 존중, 정의, 정직성, 공동체적 윤리성 강조. 청지기(stewardship) 책무 활동","src":"기출 2024-9"},{"t":"서번트 리더십은 지능·사회적 지위·교육 정도·외모를 강조하지 않는다(그것은 자질이론)","src":"기출 2024-9"},{"t":"서번트 리더십은 사회복지조직 관리에 적합하고, 생산성 측면에서 자발적 행동의 정도를 중시한다","src":"기출 2023-10"}]},{"머리":"조직문화","줄":[{"t":"조직문화: 조직의 정체성을 결정하는 일련의 가치와 신념","src":"기출 2024-8"},{"t":"조직문화는 구성원의 일체감과 정체감 형성에 기여한다","src":"기출 2024-8"},{"t":"조직의 믿음과 가치가 깊게 공유될수록 조직문화가 강해진다","src":"기출 2024-8"},{"t":"조직문화는 조직 내에서 자연적으로 생길 수 있다","src":"기출 2024-8"},{"t":"경직된 조직문화는 불확실한 환경에 대처하는 데 방해가 된다","src":"기출 2024-8"},{"t":"샤인(Schein) 조직문화 3수준: 인공물(가시적 요소) - 신봉가치 - 기본가정","src":"보충"}]},{"머리":"조직변화(혁신)","줄":[{"t":"혁신: 목표를 더 효과적으로 달성하기 위한 인위적이고 계획적인 활동","src":"기출 2023-23"},{"t":"사회환경 변화와 조직 혁신은 관련이 있다. 조직 내부환경을 고려하지 않고 추진하면 성공하기 어렵다","src":"기출 2023-23"},{"t":"혁신 방해요인: 무사안일주의, 비전 영향력 과소평가, 비전에 대한 불충분한 의사소통, 변화를 막는 조직구조·보상체계 유지","src":"기출 2024-25"},{"t":"핵심리더의 변화노력에 대한 구성원의 공개 지지는 방해요인이 아니라 촉진요인","src":"기출 2024-25"},{"t":"레윈의 변화 3단계: 해빙 - 변화 - 재동결","src":"보충"},{"t":"코터의 8단계 변화(보충): 위기의식 고취, 변화주도팀 구성, 비전 개발, 비전 소통, 권한 위임·장애 제거, 단기 성과 창출, 성과 통합·추가 변화, 문화 정착","src":"보충"}]}],"함정":[{"x":"블레이크와 머튼(R. Blake & J. Mouton)의 관리격자 모형은 자질이론 중 하나이다.","o":"관리격자 모형은 행동이론 중 하나다.","src":"기출 2022-20"},{"x":"블레이크와 머튼의 관리격자 모형에서 가장 바람직한 행동유형은 극단에 치우치지 않은 중도형이다.","o":"관리격자 모형에서 가장 바람직한 유형은 팀형(9.9)이다.","src":"기출 2022-20"},{"x":"퀸(R. Quinn)의 경쟁가치 리더십 모형은 행동이론의 대표적 모형이다.","o":"퀸의 경쟁가치 모형은 행동이론의 대표 모형이 아니다(조직문화·상황 계열).","src":"기출 2022-20"},{"x":"퀸의 경쟁가치 리더십 모형에서는 조직환경의 변화에 따라 리더십이 달라져서는 안 된다는 것을 강조한다.","o":"경쟁가치 모형은 조직환경의 변화에 따라 리더십이 달라질 수 있다고 본다.","src":"기출 2022-20"},{"x":"의사결정의 시간과 에너지가 절약될 수 있다.","o":"참여적(분권적) 의사결정은 시간과 에너지가 더 든다.","src":"기출 2022-21"},{"x":"행동이론에서 컨트리클럽형(country club management)은 사람에 대한 관심과 일에 대한 관심이 모두 높은 리더이다.","o":"컨트리클럽형(1.9)은 사람에 대한 관심은 높고 일에 대한 관심은 낮은 리더다. 둘 다 높은 유형은 팀형(9.9).","src":"기출 2023-10"},{"x":"변혁적 리더십은 부하 직원의 변화를 필요로 하지 않는다.","o":"변혁적 리더십은 부하 직원의 변화(비전 공유)를 필요로 한다.","src":"기출 2023-23"},{"x":"사회환경 변화와 조직 혁신은 무관하다.","o":"사회환경 변화와 조직 혁신은 관련이 있다.","src":"기출 2023-23"},{"x":"조직 내부환경을 고려하지 않고 변화를 추진할 때 혁신이 성공한다.","o":"조직 내부환경을 고려하지 않고 변화를 추진하면 혁신이 성공하기 어렵다.","src":"기출 2023-23"},{"x":"변혁적 리더십은 조직보다는 개인의 사적 이익을 강조한다.","o":"변혁적 리더십은 개인의 사적 이익보다 조직(공동 목표)을 강조한다.","src":"기출 2023-23"},{"x":"경직된 조직문화는 불확실한 환경에 대처하도록 돕는다.","o":"경직된 조직문화는 불확실한 환경에 대처하는 데 방해가 된다.","src":"기출 2024-8"},{"x":"효과성과 효율성에 대한 관심을 교차하여 유형화하였다.","o":"관리격자는 생산(일)에 대한 관심과 인간(사람)에 대한 관심을 교차해 유형화한다.","src":"기출 2025-9"},{"x":"이상적 유형은 컨트리클럽형(1.9)이다.","o":"이상적 유형은 팀형(9.9)이다.","src":"기출 2025-9"},{"x":"팀형(9.9)은 과업성과보다는 구성원의 사기와 공동체의식을 중시한다.","o":"팀형(9.9)은 과업성과와 인간관계 모두에 높은 관심을 둔다. 사기·공동체의식만 중시하는 것은 컨트리클럽형(1.9).","src":"기출 2025-9"},{"x":"무기력형(1.1)은 인간적 요소에 최대의 관심을 갖는다.","o":"무력형(1.1)은 인간과 일 모두에 관심이 낮다. 인간적 요소에 최대 관심은 컨트리클럽형(1.9).","src":"기출 2025-9"}]},"#6":{"묶음":[{"머리":"인적자원관리의 영역과 구성요소","줄":[{"t":"인적자원관리 구성요소: 확보(직원모집·심사·채용) · 개발(훈련·지도·감독) · 보상(임금·복리후생) · 유지(인적자원 유지·이직관리)","src":"기출 2024-11"},{"t":"승진·근태관리는 '정치'라는 구성요소가 아니다. 구성요소에 정치는 없다","src":"기출 2024-11"},{"t":"인적자원관리 영역: 채용, 배치, 평가, 승진 등. 재무는 인적자원관리 영역이 아니다","src":"기출 2021-11"},{"t":"인적자원관리는 직원채용, 직무수행 평가, 직원개발, 동기부여를 위한 보상관리, 경력개발, 직무만족도 개선, 소진관리를 포함한다","src":"기출 2023-11"},{"t":"목표관리법(MBO)으로 직원을 평가할 수 있다","src":"기출 2023-11"},{"t":"직원 모집과 채용: 외부에서 잠재적 역량을 가진 사람을 찾거나 내부에서 역량 있는 사람을 찾는 과정. 업무능력·인성·헌신 등을 고려","src":"기출 2026-7"},{"t":"이직관리, 조직 오리엔테이션, 교육훈련, 경제적 보상은 모집·채용과 구별되는 별도 영역","src":"기출 2026-7"}]},{"머리":"직무분석·직무설계·직무평가·직무기술서와 직무명세서","줄":[{"t":"직무설계: 직무 내용, 수행방법, 직무 간의 관계 등을 설정","src":"기출 2025-10"},{"t":"직무분석: 직무의 내용·요건을 조사·분석하는 과정. 일의 종류·난이도·책임수준이 유사한 직급으로 묶는 것은 직무분류(직급분류)","src":"기출 2025-10, 보충"},{"t":"직무평가: 직무 자체의 상대적 가치를 평가(보수 결정의 기초). 직무에 종사하는 직원 평가가 아니다","src":"기출 2025-10, 보충"},{"t":"직무분석 후에 직무기술서와 직무명세서를 작성한다. 직무분석이 직무명세 이후에 가능한 것이 아니다","src":"기출 2022-19, 2026-23"},{"t":"직무기술서(job description): 직무의 성격·내용·수행방법·책임·행동·작업조건 등을 정리한 문서. 직무명칭, 직무장비, 직무환경, 작업수행 표준화 내용도 포함","src":"기출 2021-13, 2023-12, 2026-23, 2025-10"},{"t":"직무기술서에 급여 수준은 포함되지 않는다","src":"기출 2021-13"},{"t":"직무명세서(job specification): 특정 직무수행에 필요한 지식·기능·능력·자격, 교육수준 등 작성","src":"기출 2022-19, 2023-12, 2025-10"},{"t":"직무명세서와 직무기술서는 직원 신규채용 이전에 작성한다(직무분석 이후)","src":"기출 2026-23"},{"t":"직무평가는 조직목표 달성에 대한 구성원의 기여도를 고려한다","src":"기출 2022-19"},{"t":"직무분석 방법(보충): 관찰법, 면접법, 질문지법, 작업일지법, 중요사건법","src":"보충"},{"t":"직무평가 방법(보충): 서열법, 분류법, 점수법, 요소비교법","src":"보충"}]},{"머리":"직무수행평가(성과평가)","줄":[{"t":"직무수행평가 순서: 직무수행 기준 확립 - 기대치를 직원에게 전달 - 평가도구로 실제 직무수행 측정 - 기준과 비교 - 직원과 평가결과 회의","src":"기출 2024-13"},{"t":"성과평가 목적: 인적자원개발을 위한 방향과 내용 확보, 직무수행이 조직 전략에 부합하는지 파악, 임금·승진·전환배치·해고 등 정보 획득","src":"기출 2026-9"},{"t":"사회복지대상자 수급이력 통합은 직원 성과평가 목적이 아니다","src":"기출 2026-9"},{"t":"평가방법(보충): 도표평정척도법, 행동기준평정척도(BARS), 체크리스트법, 서열법, 강제배분법, 중요사건기록법, MBO, 다면(360도)평가","src":"보충"},{"t":"평가자 오류(보충): 후광효과, 관대화·엄격화·중심화 경향, 최근효과, 유사효과(자기와 닮은 사람 선호), 대비오류","src":"보충"}]},{"머리":"직원개발·훈련","줄":[{"t":"OJT(직무를 통한 연수): 일반적으로 상사나 선배를 통해, 일상 업무를 통해 이루어진다. 외부 전문교육기관 제공은 Off-JT","src":"기출 2021-12"},{"t":"OJT 보기 중 외부 전문교육기관 제공은 Off-JT, 자기개발 비용 지원은 별도 방식(기출 2021-12 정답표기 검수 필요)","src":"기출 2021-12"},{"t":"강의: 짧은 시간에 많은 사람을 대상으로 교육내용을 체계적으로 전달할 때 사용(예: 시설평가제도 이해 교육)","src":"기출 2024-12"},{"t":"Off-JT 방법(보충): 강의, 토의, 역할연기(role playing), 소시오드라마, 감수성 훈련, 사례연구, 멘토링","src":"보충"},{"t":"멘토링: 경험 많은 선배가 후배를 지도·조언하는 방식(보충)","src":"보충"}]},{"머리":"슈퍼비전","줄":[{"t":"슈퍼비전 3기능: 행정적 기능, 교육적 기능, 지지적 기능","src":"기출 2023-13"},{"t":"행정적 기능: 효율적으로 일하는 구조와 자원 제공. 지지적 기능: 직원의 정신적·심리적 부담 완화(교육적 기능이 아니다)","src":"기출 2025-11"},{"t":"슈퍼비전은 소진 발생 및 예방에 영향을 미친다","src":"기출 2023-13"},{"t":"동료집단 간에도 슈퍼비전이 수행된다(동료 슈퍼비전). 위계서열이 없는 조직에서만 수행되는 것이 아니다","src":"기출 2023-13, 2026-21"},{"t":"슈퍼바이저는 직속상관이나 중간관리자가 주로 담당한다. 관리자·중재자·멘토 역할","src":"기출 2023-13, 2025-11"},{"t":"슈퍼비전 구성요소: 슈퍼바이지, 슈퍼바이저, 클라이언트, 조직","src":"기출 2025-11"},{"t":"슈퍼바이저 역할: 작업환경 구축, 지식과 기술 제공, 심리적 안정·동기부여, 서비스 지원. 비생산적 부서를 해체·축소하는 것은 역할이 아니다","src":"기출 2026-12"},{"t":"리더십과 슈퍼비전의 공통점: 슈퍼바이저가 리더 역할 수행 가능, 동료 간 수행 가능, 직무수행 과정에서 이루어짐, 교육·훈련 기능","src":"기출 2026-21"}]},{"머리":"소진관리","줄":[{"t":"소진(burnout): 직무 스트레스가 누적되어 에너지가 고갈된 상태. 직무만족도 개선과 소진관리는 인적자원관리에 포함","src":"기출 2023-11, 보충"},{"t":"매슬랙(Maslach) 소진 3요소: 정서적 고갈, 비인격화(냉소), 개인적 성취감 감소","src":"보충"},{"t":"소진 예방: 슈퍼비전, 업무량 조정, 휴가·휴식, 자기관리 교육, 조직 지지(보충)","src":"보충"}]}],"함정":[{"x":"동기부여를 위한 보상관리는 해당되지 않는다.","o":"동기부여를 위한 보상관리도 인적자원관리에 해당한다.","src":"기출 2023-11"},{"x":"동료집단 간에는 슈퍼비전이 수행되지 않는다.","o":"동료집단 간에도 슈퍼비전이 수행된다.","src":"기출 2023-13"},{"x":"교육적 기능은 직원의 정신적, 심리적 부담을 완화한다.","o":"지지적 기능이 직원의 정신적·심리적 부담을 완화한다. 교육적 기능은 지식·기술 향상.","src":"기출 2025-11"},{"x":"직무명세서와 직무기술서는 직무분석 이전에 작성한다.","o":"직무명세서와 직무기술서는 직무분석 이후에 작성한다.","src":"기출 2026-23"}]},"#7":{"묶음":[{"머리":"예산모형 총정리","줄":[{"t":"품목별 예산(LIB): 수입과 지출을 항목(품목)별로 명시. 전년도 예산을 근거로 편성. 통제 지향","src":"기출 2021-14, 2023-14, 2025-12"},{"t":"성과주의 예산(PBS): 업무(사업)에 중점을 둔 관리지향 예산. 단위원가 x 업무량 = 예산액","src":"기출 2021-14, 2025-12"},{"t":"성과주의 예산은 전년도 사업의 성과를 고려하여 수립한다","src":"기출 2023-14"},{"t":"기획예산제도(PPBS): 장기적 기획과 단기적 예산편성을 프로그램 작성을 통해 결합. 미래 비용을 고려한다. 계획 지향","src":"기출 2021-14, 2023-14, 2025-12"},{"t":"PPBS는 국가의 장기적 계획 수립을 위한 예산이다. '단기적 계획 수립을 위한 장기적 예산편성'으로 뒤바꾼 설명은 오답","src":"기출 2023-14"},{"t":"영기준 예산(ZBB): 전년도 예산을 고려하지 않고 편성. 예산의 효율성 중시. 비용-편익분석·비용-효과분석을 거친다","src":"기출 2021-14, 2023-14, 2025-12"},{"t":"프로그램 예산: 사업 목적(프로그램)을 강조한다. 지출 품목을 강조하는 것은 품목별 예산","src":"기출 2025-12"},{"t":"영기준 예산 도구(보충): 의사결정 패키지, 우선순위 순위 결정","src":"보충"},{"t":"예산 순서·특징 비교(보충): 통제(LIB) - 관리(PBS) - 계획(PPBS) - 감축·재량(ZBB)","src":"보충"}]},{"머리":"예산 원칙·통제","줄":[{"t":"예산집행 통제 기제: 개별 기관의 제약조건·요구사항·기대사항에 맞게 고안(개별화), 예외적 상황에 적용되는 규칙 명시, 보고 규정, 필요시 규칙 개정","src":"기출 2024-15"},{"t":"예산집행 통제에는 강제성 있는 규정을 둔다(강제의 원칙). 강제 규정을 두지 않는다는 설명은 오답","src":"기출 2024-15"},{"t":"예산 통제 원칙: 강제, 개별화, 예외, 보고, 개정. 접근성의 원칙은 포함되지 않는다. 효율성 포함 여부는 교재마다 다르다(검수)","src":"기출 2022-10, 보충"}]},{"머리":"사회복지법인·시설 예산 편성 절차","줄":[{"t":"회계연도: 법인과 시설은 정부의 회계연도에 따른다(1월 1일~12월 31일). 어린이집만 3월 1일~다음 해 2월 말일","src":"사회복지법인 및 사회복지시설 재무ㆍ회계 규칙 제3조"},{"t":"예산편성지침: 법인 대표이사가 회계연도 개시 1월 전까지 정한다","src":"사회복지법인 및 사회복지시설 재무ㆍ회계 규칙 제9조제1항"},{"t":"시장ㆍ군수ㆍ구청장은 특히 필요한 사항에 관해 예산편성지침을 정해 회계연도 개시 2월 전까지 통보할 수 있다","src":"사회복지법인 및 사회복지시설 재무ㆍ회계 규칙 제9조제2항"},{"t":"법인 대표이사와 시설의 장은 예산을 편성해 법인 이사회 의결 및 시설운영위원회 보고를 거쳐 확정한다","src":"사회복지법인 및 사회복지시설 재무ㆍ회계 규칙 제10조제1항"},{"t":"법인이 설치ㆍ운영하는 시설은 시설운영위원회에 보고한 후 법인 이사회 의결을 거쳐 확정한다","src":"사회복지법인 및 사회복지시설 재무ㆍ회계 규칙 제10조제1항, 기출 2024-14"},{"t":"확정한 예산을 회계연도 개시 5일 전까지 관할 시장ㆍ군수ㆍ구청장에게 제출","src":"사회복지법인 및 사회복지시설 재무ㆍ회계 규칙 제10조제2항"},{"t":"시장ㆍ군수ㆍ구청장은 예산을 제출받으면 20일 이내에 세입ㆍ세출명세서를 시ㆍ군ㆍ구 게시판과 인터넷 홈페이지에 20일 이상 공고하고, 법인ㆍ시설도 20일 이상 공고하게 한다","src":"사회복지법인 및 사회복지시설 재무ㆍ회계 규칙 제10조제4항"},{"t":"예산 편성 및 결정 절차 순서(법인 산하 시설): 예산 편성 - 시설운영위원회 보고 - 이사회 의결 - 지방자치단체 제출 - 예산 공고","src":"사회복지법인 및 사회복지시설 재무ㆍ회계 규칙 제10조, 기출 2025-14"},{"t":"사회복지관 등 일부 시설은 별표 5·6의 세입ㆍ세출예산과목 구분에 따라 편성한다(사회복지관, 노인복지관, 장애인 지역사회재활시설, 다함께돌봄센터, 지역아동센터 등)","src":"사회복지법인 및 사회복지시설 재무ㆍ회계 규칙 제10조제3항"}]},{"머리":"예산에 첨부할 서류","줄":[{"t":"예산 첨부서류: 예산총칙","src":"사회복지법인 및 사회복지시설 재무ㆍ회계 규칙 제11조제1항제1호"},{"t":"예산 첨부서류: 세입ㆍ세출명세서","src":"사회복지법인 및 사회복지시설 재무ㆍ회계 규칙 제11조제1항제2호"},{"t":"예산 첨부서류: 추정재무상태표","src":"사회복지법인 및 사회복지시설 재무ㆍ회계 규칙 제11조제1항제3호"},{"t":"예산 첨부서류: 추정수지계산서","src":"사회복지법인 및 사회복지시설 재무ㆍ회계 규칙 제11조제1항제4호"},{"t":"예산 첨부서류: 임직원 보수 일람표","src":"사회복지법인 및 사회복지시설 재무ㆍ회계 규칙 제11조제1항제5호"},{"t":"예산 첨부서류: 예산을 의결한 이사회 회의록 또는 예산을 보고받은 시설운영위원회 회의록 사본","src":"사회복지법인 및 사회복지시설 재무ㆍ회계 규칙 제11조제1항제6호"},{"t":"사업수입 명세서는 첨부서류 목록에 없다","src":"사회복지법인 및 사회복지시설 재무ㆍ회계 규칙 제11조, 기출 2022-11"},{"t":"단식부기 처리 시 제1·2·5·6호 서류만 첨부 가능. 소규모 시설(국가·지자체·법인 외 설치, 거주자 정원 또는 일일평균 이용자 20명 이하)은 제2호, 제5호(노인장기요양기관만), 제6호만 첨부 가능","src":"사회복지법인 및 사회복지시설 재무ㆍ회계 규칙 제11조제1항"}]},{"머리":"준예산·추가경정예산·전용·이월·회계 구분","줄":[{"t":"준예산: 회계연도 개시 전까지 예산이 성립되지 않으면 시장ㆍ군수ㆍ구청장에게 사유를 보고하고, 예산 성립 때까지 전년도 예산에 준하여 집행할 수 있다","src":"사회복지법인 및 사회복지시설 재무ㆍ회계 규칙 제12조"},{"t":"준예산 경비: 임ㆍ직원의 보수, 법인ㆍ시설운영에 직접 사용되는 필수 경비, 법령상 지급의무가 있는 경비","src":"사회복지법인 및 사회복지시설 재무ㆍ회계 규칙 제12조"},{"t":"추가경정예산: 예산 성립 후 생긴 사유로 변경이 필요할 때 제10조·제11조 절차에 준하여 편성ㆍ확정. 확정된 날로부터 7일 이내에 시장ㆍ군수ㆍ구청장에게 제출","src":"사회복지법인 및 사회복지시설 재무ㆍ회계 규칙 제13조, 기출 2026-16"},{"t":"추가경정예산도 이사회 의결과 시설운영위원회 보고 절차를 거친다. 의결 없이 집행하지 않는다","src":"사회복지법인 및 사회복지시설 재무ㆍ회계 규칙 제13조제1항, 기출 2026-16"},{"t":"예비비: 예측할 수 없는 예산 외 지출 또는 예산 초과지출에 충당하기 위해 세출예산에 계상할 수 있다","src":"사회복지법인 및 사회복지시설 재무ㆍ회계 규칙 제14조"},{"t":"예산의 목적 외 사용 금지: 법인회계와 시설회계 예산은 세출예산이 정한 목적 외에 사용하지 못한다","src":"사회복지법인 및 사회복지시설 재무ㆍ회계 규칙 제15조"},{"t":"예산 전용: 법인 대표이사와 시설의 장은 관ㆍ항ㆍ목 간 예산을 전용할 수 있다. 관 간 전용 또는 동일 관내 항 간 전용은 이사회 의결 또는 시설운영위원회 보고를 거쳐야 한다(소규모 시설 제외). 법인 산하 시설은 시설운영위원회 보고 후 이사회 의결","src":"사회복지법인 및 사회복지시설 재무ㆍ회계 규칙 제16조제1항, 기출 2025-13"},{"t":"예산총칙에서 전용을 제한하거나 이사회·시설 예산심의에서 삭감한 관ㆍ항ㆍ목으로는 전용할 수 없다. 관ㆍ항 간 전용 시 결산보고서 제출 때 과목 전용조서 첨부","src":"사회복지법인 및 사회복지시설 재무ㆍ회계 규칙 제16조제2항·제3항"},{"t":"세출예산 이월: 이사회 의결 및 시설운영위원회 보고를 거쳐 다음 연도에 이월 사용 가능. 법인 산하 시설은 시설운영위원회에 사전 보고한 후 이사회 의결","src":"사회복지법인 및 사회복지시설 재무ㆍ회계 규칙 제17조"},{"t":"회계 구분: 법인회계(법인 업무전반), 시설회계(시설 운영), 수익사업회계(법인 수익사업)","src":"사회복지법인 및 사회복지시설 재무ㆍ회계 규칙 제6조제1항, 기출 2025-13"},{"t":"법인 회계는 법인회계, 해당 법인이 설치ㆍ운영하는 시설의 시설회계, 수익사업회계로 구분해야 한다. 시설회계와 법인회계를 통합 관리하지 않는다","src":"사회복지법인 및 사회복지시설 재무ㆍ회계 규칙 제6조제2항, 기출 2024-14"},{"t":"회계연도 소속 구분: 수입·지출 발생과 자산·부채 증감은 그 원인이 되는 사실이 발생한 날 기준으로 연도 소속 구분","src":"사회복지법인 및 사회복지시설 재무ㆍ회계 규칙 제4조"},{"t":"출납기한: 1회계연도의 세입ㆍ세출 출납은 회계연도가 끝나는 날까지 완결","src":"사회복지법인 및 사회복지시설 재무ㆍ회계 규칙 제5조"},{"t":"사회복지법인·시설은 「사회복지법인 및 사회복지시설 재무ㆍ회계 규칙」을 따른다. 보건복지부는 「국가재정법」 적용","src":"기출 2024-14, 2025-13"},{"t":"법인회계·수익사업회계는 필요시 복식부기도 가능(기출 O)","src":"기출 2025-13"},{"t":"사회복지법인과 시설은 매년 1회 이상 감사를 실시한다","src":"기출 2024-14"},{"t":"예산총계주의: 모든 수입과 지출을 예산에 계상하는 원칙. 사회복지법인·시설 회계도 따른다","src":"보충(원문 미확인)"}]},{"머리":"재원의 종류","줄":[{"t":"공적 재원: 국가·지방자치단체의 보조금 등. 사회복지법인 등 비영리법인의 전입금은 민간 재원","src":"기출 2021-15"},{"t":"민간 재원: 후원금(증가·감소하는 유동적 재원), 서비스 이용료, 법인 전입금, 모금 등","src":"기출 2021-15"},{"t":"서비스 이용료로 재정을 충당할 수 있다. 별도 재원 확보를 위한 모금 전략이 필요하다","src":"기출 2021-15"}]}],"함정":[{"x":"기획예산제도(Planning Programming Budgeting System)는 미래의 비용을 고려하지 않는다.","o":"기획예산제도(PPBS)는 장기적 기획에 따라 미래의 비용을 고려한다.","src":"기출 2021-14"},{"x":"국가와 지방자치단체의 보조금은 포함되지 않는다.","o":"국가와 지방자치단체의 보조금도 재원에 포함된다.","src":"기출 2021-15"},{"x":"서비스 이용료로 재정을 충당할 수 없다.","o":"서비스 이용료로 재정을 충당할 수 있다.","src":"기출 2021-15"},{"x":"별도의 재원 확보를 위한 모금 전략은 불필요하다.","o":"별도의 재원 확보를 위한 모금 전략이 필요하다.","src":"기출 2021-15"},{"x":"사회복지법인 등 비영리법인의 전입금은 공적 재원이다.","o":"사회복지법인 등 비영리법인의 전입금은 민간 재원이다.","src":"기출 2021-15"},{"x":"영기준 예산(Zero Based Budgeting)은 전년도 예산 내역을 반영하여 수립한다.","o":"영기준 예산은 전년도 예산을 고려하지 않고 새로 수립한다.","src":"기출 2023-14"},{"x":"계획 예산(Planning Programming Budgeting System)은 국가의 단기적 계획 수립을 위한 장기적 예산편성 방식이다.","o":"기획예산제도(PPBS)는 국가의 장기적 계획 수립을 위한 예산편성 방식이다.","src":"기출 2023-14"},{"x":"영기준 예산(Zero Based Budgeting)은 비용-편익분석, 비용-효과분석을 거치지 않고 수립한다.","o":"영기준 예산은 비용-편익분석, 비용-효과분석을 거친다.","src":"기출 2023-14"},{"x":"성과주의 예산(Performance Budgeting)은 전년도 사업의 성과를 고려하지 않고 수립한다.","o":"성과주의 예산은 전년도 사업의 성과를 고려하여 수립한다.","src":"기출 2023-14"},{"x":"시설운영 사회복지법인인 경우, 시설회계와 법인회계는 통합하여 관리한다.","o":"시설운영 사회복지법인의 시설회계와 법인회계는 구분하여 관리한다. (법인회계·시설회계·수익사업회계)","src":"기출 2024-14"},{"x":"프로그램 예산은 사업 목적보다 지출 품목을 강조한다.","o":"프로그램 예산은 사업 목적을 강조한다. 지출 품목 강조는 품목별 예산.","src":"기출 2025-12"},{"x":"사회복지법인 대표이사는 관ㆍ항ㆍ목간 예산을 전용할 수 없다.","o":"사회복지법인 대표이사는 관ㆍ항ㆍ목 간 예산을 전용할 수 있다(관 간 전용·동일 관내 항 간 전용은 이사회 의결 또는 운영위원회 보고를 거쳐야 한다).","src":"기출 2025-13"},{"x":"예산총계주의원칙을 따르지 않는다.","o":"사회복지법인·시설도 예산총계주의 원칙을 따른다.","src":"기출 2026-16"},{"x":"회계연도 개시 후 신규 지출 사유가 발생한 경우 법인 이사회의 의결없이 집행한다.","o":"회계연도 개시 후 신규 지출 사유가 발생하면 추가경정예산을 이사회 의결 및 시설운영위원회 보고 절차에 준하여 편성ㆍ확정한 뒤 집행한다.","src":"사회복지법인 및 사회복지시설 재무ㆍ회계 규칙 제13조제1항"},{"x":"법인 산하 시설의 예산집행은 시설 운영위원회의 보고 없이 법인 이사회에서 의결한다.","o":"법인 산하 시설의 예산은 시설운영위원회에 보고한 후 법인 이사회의 의결을 거쳐 확정한다.","src":"사회복지법인 및 사회복지시설 재무ㆍ회계 규칙 제10조제1항"},{"x":"준예산은 법인 이사회의 의결을 거쳐서 보건복지부에 제출한다.","o":"준예산은 회계연도 개시 전까지 예산이 성립되지 않은 때 시장ㆍ군수ㆍ구청장에게 그 사유를 보고하고 집행한다.","src":"사회복지법인 및 사회복지시설 재무ㆍ회계 규칙 제12조"}]},"#2":{"묶음":[{"머리":"한국 사회복지행정 연대기","줄":[{"t":"1950년대: 6.25 전쟁 이후 외국원조기관 중심으로 긴급구호와 생활(수용)시설 보호가 주를 이루었다","src":"기출 2023-1, 2024-2, 2025-2"},{"t":"1960년대 외국원조기관 철수 후 자생적 사회복지단체가 성장한 것이 아니다. 외국원조 의존이 이어지다 쇠퇴했다","src":"기출 2024-2"},{"t":"1970년 「사회복지사업법」 제정: 시설 운영·감독·지원의 법적 근거 마련","src":"기출 2023-1, 2025-2"},{"t":"1980년대 후반: 사회복지전문요원 배치 시작(1987), 지역사회 이용시설(사회복지관) 증가","src":"기출 2023-1, 2024-2"},{"t":"사회복지관 정부 보조는 1980년대 말(1989 종합사회복지관 국고보조)부터. 2000년대에 처음 제도화된 것이 아니다","src":"기출 2023-1, 보충"},{"t":"1990년대: 사회복지시설 평가제도 도입. 1997년 「사회복지사업법」 개정으로 시설평가 법제화","src":"기출 2023-1, 2025-2"},{"t":"1997년 「사회복지사업법」 개정: 시설 설치기준 허가제 -> 신고제(1990년대 후반)","src":"기출 2024-2"},{"t":"1998년 사회복지공동모금회 설립","src":"기출 2025-2"},{"t":"2000년 국민기초생활보장제도 시행. 장기요양보험제도는 2008년 시행","src":"기출 2026-6, 보충"},{"t":"2008년 노인장기요양보험 도입 후에도 민간기관의 서비스 제공은 금지되지 않았다(민간 참여 확대)","src":"기출 2025-2"}]},{"머리":"한국 사회복지전달체계 개편 순서","줄":[{"t":"사회복지전문요원 제도(1987)가 먼저, 사회복지전담공무원(2000 명칭 변경) 제도가 뒤","src":"기출 2024-17, 보충"},{"t":"보건복지사무소 시범사업(1995~) -> 사회복지사무소 시범사업(2004~) 순. 동시 진행이 아니다","src":"기출 2021-17, 2024-17, 보충"},{"t":"주민생활지원서비스 전달체계(2006~)","src":"기출 2023-17, 보충"},{"t":"사회서비스 전자바우처 도입(2007)","src":"기출 2026-3, 보충"},{"t":"사회복지통합관리망(행복e음) 개통(2010)","src":"기출 2021-17, 2023-17, 보충"},{"t":"시·군·구 희망복지지원단 구축 시작(2012)","src":"기출 2026-6, 2026-3, 보충"},{"t":"지역사회복지협의체(2005 설치) -> 지역사회보장협의체로 명칭 변경(2015)","src":"기출 2022-23, 2024-17, 보충"},{"t":"읍·면·동 복지허브화 사업(2016~). 이 사업 이후에 읍면동사무소가 주민자치센터로 바뀐 것이 아니다","src":"기출 2024-17, 보충"},{"t":"지역사회 통합돌봄(커뮤니티 케어) 선도사업 시작(2019)","src":"기출 2021-17, 2026-3, 보충"},{"t":"순서 암기용 정리(기출 정답 기준): 보건복지사무소 시범 - 사회복지사무소 시범 - 주민생활지원 - 전자바우처 - 행복e음 - 희망복지지원단 - 읍면동 복지허브화 - 통합돌봄","src":"기출 2021-17, 2023-17, 2026-3"},{"t":"전자바우처 사회서비스 사업(2007)은 사회서비스원 설치(2019~) 이전","src":"기출 2024-17, 보충"},{"t":"2019년 장애등급제 폐지(2024년이 아니다). 2020년에 지역사회보장협의체가 구성된 것이 아니다","src":"기출 2026-6, 보충"},{"t":"2015년 행복e음 개통이 아니다(2010). 2012년 희망복지지원단은 맞다","src":"기출 2026-6, 보충"}]},{"머리":"미국 사회복지행정의 흐름","줄":[{"t":"자선조직협회(COS, 1877 버팔로): 우애방문, 조사·조정 -> 사회복지행정(조직화·조정)의 뿌리","src":"보충"},{"t":"인보관 운동(토인비홀 1884, 헐하우스 1889): 지역사회 조직·사회개혁","src":"보충"},{"t":"1930년대 대공황과 1935년 사회보장법: 공공부조·사회보험 확대로 공공 사회복지행정 비중이 커졌다","src":"보충"},{"t":"1960년대 빈곤과의 전쟁: 연방 지원 확대로 프로그램 관리·기획 역량이 강조되었다","src":"보충"},{"t":"1970~80년대: 재정 압박과 민영화 -> 책임성·성과·경영기법 도입이 강조되었다","src":"보충"}]}],"함정":[{"x":"2000년대에 사회복지관에 대한 정부 보조금 지원이 제도화 되었다.","o":"사회복지관 정부 보조는 1980년대 말부터다(2000년대에 처음 제도화된 것이 아님).","src":"기출 2023-1"},{"x":"1960년대 외국원조기관 철수 후 자생적 사회복지단체들이 성장했다.","o":"1960년대 외국원조기관 철수 후에도 자생적 단체가 곧바로 성장한 것이 아니다(외국원조 의존이 이어졌다).","src":"기출 2024-2"},{"x":"사회복지전담공무원 제도 이후 사회복지전문요원 제도가 실시되었다.","o":"사회복지전문요원(1987) 제도가 먼저, 사회복지전담공무원(2000) 제도가 이후다.","src":"기출 2024-17"},{"x":"보건복지사무소와 사회복지사무소 시범사업은 동시에 진행되었다.","o":"보건복지사무소(1995~) 시범사업이 먼저, 사회복지사무소(2004~) 시범사업이 이후다.","src":"기출 2024-17"},{"x":"읍·면·동 복지허브화 사업 이후 읍·면·동사무소가 주민자치센터로 변경되었다.","o":"읍·면·동 복지허브화(2016~) 사업은 읍면동 명칭 변경과 같은 흐름이 아니다. 주민자치센터 개편은 그 이전부터 진행.","src":"기출 2024-17"},{"x":"사회서비스원 설치 후 전자바우처 방식의 사회서비스 사업이 시작되었다.","o":"전자바우처 사회서비스 사업(2007)이 사회서비스원 설치(2019~)보다 먼저다.","src":"기출 2024-17"},{"x":"2008년 노인장기요양보험제도 도입으로 민간기관의 서비스 제공이 금지되었다.","o":"2008년 노인장기요양보험 도입 후에도 민간기관은 서비스를 제공한다(민간 참여 확대).","src":"기출 2025-2"},{"x":"2000년에 국민기초생활보장제도와 장기요양보험제도가 시행되었다.","o":"2000년에 국민기초생활보장제도가 시행되었고 장기요양보험제도는 2008년에 시행되었다.","src":"기출 2026-6"},{"x":"2015년에 사회복지통합관리망(행복e음)이 개통되었다.","o":"행복e음(사회복지통합관리망)은 2010년에 개통되었다.","src":"기출 2026-6"},{"x":"2020년에 지역사회보장협의체가 구성되었다.","o":"지역사회보장협의체의 전신인 지역사회복지협의체는 2005년에 설치되었다(명칭 변경 2015).","src":"기출 2026-6"},{"x":"2024년에 장애등급제가 폐지되었다.","o":"장애등급제는 2019년에 폐지되었다.","src":"기출 2026-6"}]},"#9":{"묶음":[{"머리":"기획 과정","줄":[{"t":"스키드모어(Skidmore) 기획과정 순서: 구체적 목표 설정 - 가용자원 검토 - 대안 모색 - 대안 결과예측 - 최종대안 선택 - 프로그램 실행계획 수립","src":"기출 2022-9"},{"t":"전략적 기획: 과정을 강조하므로 우선순위를 설정하고 단계적인 계획을 수립","src":"기출 2021-19"},{"t":"SWOT: 강점·약점·기회·위협 분석(전략적 기획의 환경분석 도구)","src":"보충"}]},{"머리":"기획·프로그램 관리 기법","줄":[{"t":"간트 차트(Gantt Chart): 사업별 진행시간을 파악해 단계별로 분류한 시간을 단선적 활동으로 표시. 가로축 기간, 세로축 과업","src":"기출 2021-19, 2026-13, 보충"},{"t":"간트차트: 작성이 쉽고 간단하나 일정계획 변경을 유연하게 수용하기 어렵다. 시간과 무관하게 과업을 나타내는 것이 아니다","src":"기출 2025-18, 2026-13"},{"t":"PERT(프로그램 평가 검토기법): 복잡한 과업의 순서가 보이도록 하고 임계경로를 거친다. 활동 간 상호관계와 연계성을 보여주며 임계경로와 여유시간 정보 파악","src":"기출 2021-19, 2024-20"},{"t":"PERT는 업무를 체계적으로 수행하는 데 도움이 되고, 일정변경 등 유동적인 상황에 대처하기 쉽다(대처하기 어렵다는 설명은 오답)","src":"기출 2025-18"},{"t":"PERT 기간(보충): 낙관적·가능성 높은·비관적 시간 3점 추정, 기대시간 = (낙관 + 4 x 가능성 + 비관) / 6","src":"보충"},{"t":"임계경로(CPM)를 찾아 소요시간을 단축하는 것은 PERT의 특징이다. 목표관리(MBO)의 특징이 아니다","src":"기출 2026-13"},{"t":"플로우 차트(총괄진행표): 프로그램 제공과정을 시작부터 종료까지 한눈에 볼 수 있게 도식화","src":"기출 2025-18"},{"t":"방침관리기획(PDCA): 과정별 수행 상황 점검(Plan-Do-Check-Act)을 중시. 체계이론을 적용한 모델이 아니라 목표관리 계열의 환류 순환 관리","src":"기출 2021-19, 2026-13, 보충"},{"t":"목표관리(MBO): 목표를 구성원과 함께 설정, 결과 평가. 직원 평가에 활용","src":"기출 2023-11, 보충"}]},{"머리":"집단 의사결정 기법","줄":[{"t":"명목집단기법(NGT): 대면하여 의사결정, 집단적 상호작용 최소화, 민주적 방식(투표 등)으로 최종 의사결정","src":"기출 2024-19"},{"t":"브레인스토밍: 비판 없이 다량의 아이디어를 자유롭게 제시","src":"보충"},{"t":"델파이기법: 전문가 대상 익명 설문을 반복하며 의견 수렴. 대면하지 않는다","src":"보충"},{"t":"초점집단면접(FGI): 소수 집단을 모아 주제 중심으로 토의","src":"보충"}]},{"머리":"의사결정 모형","줄":[{"t":"쓰레기통모형: 조직화된 무질서 속에서 우연히 의사결정이 이루어짐. 목표가 모호하고 조직 기술이 막연한 경우에 적용","src":"기출 2023-18, 2025-20"},{"t":"점증모형(린드블롬): 현행에서 조금씩 개선. 여러 대안을 평가해 합리적 순위를 정하는 모형은 합리모형","src":"기출 2023-18, 보충"},{"t":"합리모형: 문제 진단과 의사결정이 체계적·논리적으로 이루어지고 가장 합리적인 대안을 선택","src":"기출 2025-20, 보충"},{"t":"만족모형(사이먼): 제한된 합리성 속에서 만족할 만한 수준의 대안 선택. 문제가 분명하고 단순한 경우에 쓰는 모형이 아니다","src":"기출 2023-18, 보충"},{"t":"혼합주사모형(에치오니): 합리모형과 점증모형을 절충. 합리성과 비합리성을 절충한 모형이 쓰레기통모형이라는 설명은 오답","src":"기출 2025-20, 보충"},{"t":"연합모형(사이어트와 마치): 조직을 하위 연합체의 연합으로 보는 모형. 경제적·시장 중심 시각이 아니다","src":"기출 2023-18, 보충"},{"t":"공공선택모형: 시민을 공공재의 소비자로, 정부를 생산자(공급자)로 규정","src":"기출 2023-18, 보충"},{"t":"쓰레기통모형은 결정자 행동보다 객관적 상황 조건에 더 주의하는 모형이 아니다","src":"기출 2025-20"}]},{"머리":"프로그램 설계: 논리모델과 프로포절","줄":[{"t":"논리모델(Logic Model): 투입(input) - 활동(activity) - 산출(output) - 성과(outcome)의 내용을 도식화","src":"기출 2021-19, 2026-13"},{"t":"프로포절 구성(보충): 제목, 필요성·문제 진술, 목적·목표, 프로그램 내용·방법, 일정, 예산, 평가계획, 기대효과","src":"보충"},{"t":"목표는 구체적·측정 가능·달성 가능·현실적·기한 명시가 필요하다(SMART)","src":"보충"}]}],"함정":[{"x":"방침관리기획(PDCA)은 체계이론을 적용한 모델이다.","o":"방침관리기획(PDCA)은 계획-실행-점검-조치의 환류 순환 관리 모델이다(체계이론 적용 모델 아님).","src":"기출 2021-19"},{"x":"점증모형은 여러 대안을 평가하여 합리적 평가 순위를 정하는 모형이다.","o":"합리적 평가 순위를 정하는 모형은 합리모형이다. 점증모형은 현행에서 조금씩 개선.","src":"기출 2023-18"},{"x":"연합모형은 경제적ㆍ시장 중심적 시각에서 이루어지는 모형이다.","o":"연합모형은 조직을 하위 연합체의 타협으로 보는 모형이다. 경제적·시장 중심 시각이 아니다.","src":"기출 2023-18"},{"x":"만족모형은 주로 해결해야 할 문제가 분명하고 단순한 의사결정에 적용된다.","o":"만족모형은 제한된 합리성 아래 만족할 만한 대안을 택하는 모형이다. 문제가 분명하고 단순한 경우에 쓰는 모형이 아니다.","src":"기출 2023-18"},{"x":"공공선택모형은 시민들을 공공재의 생산자로 규정하고 정부를 소비자로 규정한다.","o":"공공선택모형은 시민을 소비자, 정부를 공급자로 본다.","src":"기출 2023-18"},{"x":"프로그램평가검토기법(PERT)은 일정변경 등 유동적인 상황을 대처하는 데 어렵다.","o":"PERT는 일정변경 등 유동적 상황에 대처하는 데 도움이 된다.","src":"기출 2025-18"},{"x":"문제 진단과 의사결정 과정이 체계적이고 논리적으로 이루어진다.","o":"문제 진단과 의사결정이 체계적·논리적으로 이루어지는 것은 합리모형. 쓰레기통모형은 우연한 결정.","src":"기출 2025-20"},{"x":"결정자의 행동보다는 객관적인 상황적 조건에 더 많은 주의를 기울인다.","o":"쓰레기통모형은 객관적 상황보다 참여자·기회·문제의 우연한 결합에 좌우된다.","src":"기출 2025-20"},{"x":"가장 합리적인 대안을 선택하는 모형이다.","o":"가장 합리적인 대안을 선택하는 모형은 합리모형이다.","src":"기출 2025-20"},{"x":"합리성과 비합리성을 절충한 모형이다.","o":"합리성과 비합리성을 절충한 모형은 혼합주사모형이다.","src":"기출 2025-20"},{"x":"목표관리이론(MBO) 방식은 임계경로를 찾아 프로그램 소요시간을 단축할 수 있도록 한다.","o":"임계경로를 찾아 소요시간을 단축하는 것은 PERT다. MBO는 목표를 공동 설정해 평가.","src":"기출 2026-13"},{"x":"프로그램 평가기법(PERT)은 기간을 가로축, 과업을 세로축에 표기하여 시간별 과업을 제시한다.","o":"PERT는 임계경로와 활동 간 관계를 보여준다. 기간을 가로축, 과업을 세로축에 표기하는 것은 간트 차트.","src":"기출 2026-13"},{"x":"간트도표(Gantt Chart)는 시간과는 무관한 여러가지 과업 진행을 나타낸다.","o":"간트 차트는 시간(기간)에 따른 과업 진행을 나타낸다.","src":"기출 2026-13"},{"x":"방침관리기획(PDCA)은 과정별 수행 상황 점검보다 결과를 중시한다.","o":"PDCA는 과정별 수행 상황 점검을 중시한다.","src":"기출 2026-13"}]},"#8":{"묶음":[{"머리":"마케팅의 개념과 필요성","줄":[{"t":"사회복지 마케팅: 이윤추구보다 사회적 가치 실현에 주안점. 교환되는 것은 유형의 재화보다 무형의 서비스","src":"기출 2023-20"},{"t":"마케팅 대상: 비물질적 서비스도 대상이다. 클라이언트 집단도 마케팅 대상이다","src":"기출 2021-21, 2025-25"},{"t":"영리조직에 비해 인간의 태도·행동을 변화시키기 어렵다. 조직 목표 달성과 측정이 쉽지 않다","src":"기출 2023-20"},{"t":"서비스의 생산과 소비의 동시성을 고려한다. 영리 마케팅과 달리 내구성은 해당 없음","src":"기출 2023-20, 2025-25"},{"t":"마케팅 필요성: 책임성(효과성·효율성), 고객만족을 이끌어내는 대상자 관리, 잠재적 후원자 개발·재정 확보, 서비스 개발을 위한 외부 환경분석. 대량소비와 이윤추구는 필요성이 아니다","src":"기출 2026-24"},{"t":"공익사업과 수익사업의 적절한 운영을 위해 필요. 비영리조직 간 경쟁에 대한 대응 필요. 재정자립도 마케팅 목표가 될 수 있다","src":"기출 2021-21, 2025-21"},{"t":"비영리 마케팅: 고객 욕구 충족이 핵심, 후원자에게만 초점이 있지 않다. 프로그램을 알리는 것과 재정확충 둘 다 목적","src":"기출 2025-21"},{"t":"비영리 마케팅은 책임성과 효과성이 강조되면서 중요성이 커졌다","src":"기출 2025-21"},{"t":"서비스의 특성(보충): 무형성, 비분리성(동시성), 이질성, 소멸성","src":"보충"}]},{"머리":"마케팅 믹스 4P와 마케팅 과정","줄":[{"t":"4P: 제품(Product) · 가격(Price) · 유통/장소(Place) · 촉진/판촉(Promotion). 성과(Performance)·계획·문제·프로젝트는 4P가 아니다","src":"기출 2021-20, 2026-15"},{"t":"제품: 고객의 욕구 충족을 위해 제공하는 재화나 서비스","src":"기출 2023-21"},{"t":"유통(Place): 고객이 서비스를 쉽게 이용하도록 하는 조직적 활동","src":"기출 2023-21"},{"t":"가격(Price)은 판매자가 이윤 극대화를 위해 임의로 정하는 금액이 아니다. 촉진(Promotion)은 판매 실적에 따른 승진 제도가 아니다","src":"기출 2023-21"},{"t":"사회복지서비스 마케팅 과정 순서: 고객 및 시장 조사 - STP 전략 설계 - 마케팅 믹스 - 고객관계관리(CRM)","src":"기출 2024-21"},{"t":"STP: 시장세분화(Segmentation) - 표적시장 선정(Targeting) - 포지셔닝(Positioning). 세분화는 시장을 임의로 구분하지 않고 기준에 따라 구분","src":"기출 2024-21, 2025-25, 보충"},{"t":"확장 믹스 7P(보충): 사람, 과정, 물리적 증거 추가","src":"보충"}]},{"머리":"마케팅 기법의 유형","줄":[{"t":"사회 마케팅: 대중 캠페인 등을 통해 행동변화를 유도","src":"기출 2024-22, 2022-13"},{"t":"기업연계(공익연계) 마케팅: 명분마케팅(cause-related marketing)이라고도 함. 기업이 특정 사회적 명분과 제품 판매를 연계","src":"기출 2024-22"},{"t":"다이렉트(직접) 마케팅: 방송·잡지 등 대중매체 활용 방식이 아니다. 우편·전화·이메일 등으로 특정 개인에게 직접 접근","src":"기출 2024-22, 보충"},{"t":"데이터베이스 마케팅: 이용자에 대한 각종 정보를 수집·분석하여 활용","src":"기출 2024-22"},{"t":"고객관계관리(CRM) 마케팅: 개별 고객 특성에 맞춘 서비스를 지속적으로 제공. 학부모들이 후원 의사를 밝히자 맞춤 프로그램을 기획해 후원자로 참여시킨 사례","src":"기출 2024-22, 2022-13"}]},{"머리":"자원개발(모금)","줄":[{"t":"사회복지공동모금회는 1998년 설립","src":"기출 2025-2"},{"t":"모금 방법(보충): 개인 후원(정기후원·ARS), 기업 후원, 자선행사, 우편모금(DM), 온라인 모금, 특별모금(기획모금)","src":"보충"},{"t":"후원금은 증가·감소하는 유동적 재원이므로 별도 모금 전략이 필요하다","src":"기출 2021-15"}]}],"함정":[{"x":"영리추구의 목적으로만 마케팅을 추진한다.","o":"마케팅은 영리 추구만이 목적이 아니다. 고객 욕구 충족과 공익 가치를 함께 추구한다.","src":"기출 2021-21"},{"x":"비영리조직 간의 경쟁에 대한 대응은 필요없다.","o":"비영리조직 간 경쟁에 대한 대응이 필요하다.","src":"기출 2021-21"},{"x":"사회복지조직이 제공하는 비물질적인 서비스는 마케팅 대상이 아니다.","o":"비물질적 서비스도 마케팅 대상이다.","src":"기출 2021-21"},{"x":"비영리조직의 재정자립은 마케팅의 목표가 될 수 없다.","o":"비영리조직의 재정자립도 마케팅의 목표가 될 수 있다.","src":"기출 2021-21"},{"x":"조직의 목표달성과 측정이 용이하다.","o":"사회복지조직은 목표 달성과 측정이 쉽지 않다.","src":"기출 2023-20"},{"x":"다이렉트 마케팅은 방송이나 잡지 등 대중매체를 활용하는 방식이다.","o":"다이렉트 마케팅은 특정 개인에게 직접 접근한다. 방송·잡지 등 대중매체를 쓰는 방식이 아니다.","src":"기출 2024-22"},{"x":"고객 욕구충족보다는 판매에 집중한다.","o":"비영리 마케팅은 고객 욕구 충족을 중시한다.","src":"기출 2025-21"},{"x":"이윤을 남기는 것이 최우선 목표이다.","o":"비영리 마케팅은 이윤보다 사회적 가치와 서비스 목적이 우선이다.","src":"기출 2025-21"},{"x":"후원자에게만 초점이 맞춰져 있다.","o":"비영리 마케팅은 후원자뿐 아니라 서비스 이용자·지역사회 등을 대상으로 한다.","src":"기출 2025-21"},{"x":"비영리조직 마케팅 목적은 프로그램을 알리는 것이지 재정확충은 아니다.","o":"비영리조직 마케팅은 프로그램 홍보와 재정확충 둘 다 목적이다.","src":"기출 2025-21"}]},"#11":{"묶음":[{"머리":"사회복지정보시스템","줄":[{"t":"사회보장정보시스템(범정부): 사회복지사업 정보와 지원대상자의 자격정보·수급이력정보 등을 통합관리. 소득·재산·인적자료·수급이력정보를 연계해 정확한 대상자 선정과 효율적 복지업무 처리를 지원","src":"기출 2022-8"},{"t":"복지로: 복지서비스 정보를 안내하고 온라인 신청을 지원하는 복지포털(보충)","src":"보충"},{"t":"사회복지시설정보시스템: 시설 운영·종사자 등 시설 관련 정보를 관리하는 시스템(보충)","src":"보충"},{"t":"사회서비스 전자바우처시스템: 바우처 방식 사회서비스의 이용·결제·정산 관리(보충)","src":"보충"},{"t":"사회복지통합관리망(행복e음): 2010년 개통(보충)","src":"보충"}]},{"머리":"정보관리의 효과와 한계","줄":[{"t":"효과: 조직의 업무효율성 증대, 대상자 관리의 정확성·객관성 확보","src":"기출 2023-19"},{"t":"효과: 사회복지행정가가 정보를 체계적으로 다룰 수 있다","src":"기출 2023-19"},{"t":"한계: 클라이언트 사생활 침해 가능성이 높아졌다","src":"기출 2023-19"},{"t":"정보화로 학습조직의 필요성이 감소한 것이 아니다","src":"기출 2023-19"},{"t":"정보관리가 필요한 이유: 책임성 강화, 적절한 정보체계 구축, 종사자 전문성 강화, 조직 효과성 제고. 정보관리가 조직에서 최우선이기 때문은 아니다","src":"기출 2025-19"},{"t":"정보관리와 홍보는 마케팅과 연결된다. 홍보 수단(보충): 보도자료, 소식지, 홈페이지, SNS","src":"보충"}]}],"함정":[{"x":"학습조직의 필요성이 감소하였다.","o":"정보화에도 학습조직의 필요성은 감소하지 않았다.","src":"기출 2023-19"},{"x":"사회복지조직에서 정보관리가 최우선이기 때문이다.","o":"정보관리가 최우선이기 때문이 아니라 책임성 강화 등 목적 때문이다.","src":"기출 2025-19"}]}};
